/* Todas as regras copiadas do Discord RioRise - Brasil RP (canais de regras). Usadas pelo Assistente. Atualizado em 13/11/2026. */
const REGRAS_COMPLETAS = [{"g":"Regras das organizações","b":"REGRAS OFICIAIS DA POLÍCIA","s":"REGRAS OFICIAIS DA POLÍCIA","n":"","t":"Turno de trabalho: das 08:00 às 00:00.\nDurante este período, todos os policiais devem estar em serviço, uniformizados e equipados.","p":""},{"g":"Regras das organizações","b":"REGRAS OFICIAIS DA POLÍCIA","s":"REGRAS OFICIAIS DA POLÍCIA","n":"","t":"Intervalo: das 12:00 às 13:00.\nA divisão de turnos é permitida para melhor cobertura da cidade.","p":""},{"g":"Regras das organizações","b":"REGRAS OFICIAIS DA POLÍCIA","s":"REGRAS OFICIAIS DA POLÍCIA","n":"","t":"Limite de líderes:\n13 delegados + Líder (total de 14).","p":""},{"g":"Regras das organizações","b":"REGRAS OFICIAIS DA POLÍCIA","s":"REGRAS OFICIAIS DA POLÍCIA","n":"","t":"O Comandante e os Oficiais têm autoridade para reportar infrações e aplicar medidas disciplinares de forma independente ao detectar um infrator.","p":""},{"g":"Regras das organizações","b":"REGRAS OFICIAIS DA POLÍCIA","s":"DISCIPLINA E HIERARQUIA","n":"","t":"Respeite sempre a cadeia de comando.","p":""},{"g":"Regras das organizações","b":"REGRAS OFICIAIS DA POLÍCIA","s":"DISCIPLINA E HIERARQUIA","n":"","t":"Decisões do comando são finais e devem ser cumpridas sem questionamentos IC.","p":""},{"g":"Regras das organizações","b":"REGRAS OFICIAIS DA POLÍCIA","s":"DISCIPLINA E HIERARQUIA","n":"","t":"O respeito entre colegas é obrigatório.\nDiscussões, ofensas, desrespeito ou atitudes tóxicas (IC ou OOC) serão punidas.\nPunição: desligamento da organização por descumprimento","p":"desligamento da organização por descumprimento"},{"g":"Regras das organizações","b":"REGRAS OFICIAIS DA POLÍCIA","s":"DISCIPLINA E HIERARQUIA","n":"","t":"É proibido o uso indevido do rádio, megafone ou chat policial para piadas, assuntos pessoais ou flood.\nPunição: desligamento da organização por descumprimento","p":"desligamento da organização por descumprimento"},{"g":"Regras das organizações","b":"REGRAS OFICIAIS DA POLÍCIA","s":"DISCIPLINA E HIERARQUIA","n":"","t":"Policiais devem agir com profissionalismo e neutralidade sem abuso de poder ou favorecimentos.","p":""},{"g":"Regras das organizações","b":"REGRAS OFICIAIS DA POLÍCIA","s":"DISCIPLINA E HIERARQUIA","n":"","t":"É proibido pedir promoções ou vantagens.\nA progressão depende de mérito, disciplina e tempo de serviço.\nPunição: desligamento da organização","p":"desligamento da organização"},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"REGRAS DE PATRULHA E OPERAÇÕES","n":"","t":"Patrulhas:\nDevem ser feitas com no mínimo 3 policiais por viatura (VTR).\nPatrulhas com menos de 3 policiais só com autorização do Comandante ou acompanhadas por patente superior.","p":""},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"REGRAS DE PATRULHA E OPERAÇÕES","n":"","t":"É proibido o uso de taser em veículos em movimento, salvo em casos extremos com autorização superior.\nPunição: desligamento da organização caso descumpra sem uma ordem superior","p":"desligamento da organização caso descumpra sem uma ordem superior"},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"REGRAS DE PATRULHA E OPERAÇÕES","n":"","t":"Uso de armas de fogo:\nSomente é permitido se o suspeito abrir fogo contra civis ou policiais.","p":""},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"REGRAS DE PATRULHA E OPERAÇÕES","n":"","t":"Comunicação:\nTodas as perseguições, tiroteios e prisões devem ser reportadas via rádio.","p":""},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"REGRAS DE PATRULHA E OPERAÇÕES","n":"","t":"Reforço:\nPoliciais podem solicitar viaturas adicionais, desde que a corporação mantenha superioridade numérica sobre os criminosos.","p":""},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"REGRAS DE PATRULHA E OPERAÇÕES","n":"","t":"Armamento pesado:\nRestrito a operações especiais ou situações de alto risco, com autorização de comando.","p":""},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"ABORDAGENS E PROCEDIMENTOS","n":"","t":"Toda abordagem deve ser feita com respeito e clareza.\nO policial deve se identificar e informar o motivo da abordagem.","p":""},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"ABORDAGENS E PROCEDIMENTOS","n":"","t":"Para revistar mulheres, é obrigatória a presença de uma policial feminina.\nCaso não haja, a revista só poderá ocorrer com consentimento do cidadão via chat.","p":""},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"ABORDAGENS E PROCEDIMENTOS","n":"","t":"Caso o cidadão ofereça risco ou tente fugir, o policial pode algemá-lo imediatamente.","p":""},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"ABORDAGENS E PROCEDIMENTOS","n":"","t":"Nenhum jogador deve atrapalhar a comunicação entre policial e cidadão\n(sons altos, xingamentos, provocações, etc. resultarão em punição).\nPunição: mute por ruídos ( 3.26 )","p":").\nPunição: mute por ruídos ( 3.26 )"},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"ABORDAGENS E PROCEDIMENTOS","n":"","t":"O uso de força letal é permitido apenas em legítima defesa ou para proteger civis e policiais.","p":""},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"PROCEDIMENTOS DE PRISÃO","n":"","t":"Antes de colocar o suspeito na viatura (VTR), o policial deve explicar o motivo da prisão e o tempo de detenção.","p":""},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"PROCEDIMENTOS DE PRISÃO","n":"","t":"Caso o cidadão levante as mãos ou se renda, é considerado rendido e não pode reagir.","p":""},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"PROCEDIMENTOS DE PRISÃO","n":"","t":"A Polícia não deve impedir o trabalho dos advogados dentro do presídio.\nPunição: aviso verbal, caso repita aviso de 1/3","p":"aviso verbal, caso repita aviso de 1/3"},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"PROCEDIMENTOS DE PRISÃO","n":"","t":"Advogados não podem liberar presos administrativos.\nPunição: 60 minutos de cadeia ( 4.22 - FAIL )","p":"60 minutos de cadeia ( 4.22 - FAIL )"},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"CONDUTA E RESTRIÇÕES INTERNAS","n":"","t":"O policial deve manter conduta exemplar dentro e fora de serviço.\nA imagem da corporação reflete o servidor.","p":""},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"CONDUTA E RESTRIÇÕES INTERNAS","n":"","t":"É PROIBIDO:\nUsar viaturas para fins pessoais.\nFazer quests, caçadas ou eventos durante o serviço.\nTrabalhar em outros empregos no expediente.\nColaborar ou se associar a criminosos.\nUsar drogas, bebidas alcoólicas ou armas ilegais.\nUtilizar rádio, megafone ou chat para brincadeiras.\nMisturar IC e OOC em situações de RP.\nPunição: desligamento da organização + blacklist","p":"desligamento da organização + blacklist"},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"PRESENÇA E PUNIÇÕES","n":"","t":"Mínimo de 7 horas semanais em serviço.\nPenalidades possíveis:\n• Advertência verbal\n• Advertência escrita\n• Suspensão temporária\n• Demissão\n• Inclusão em blacklist da corporação","p":"possíveis:\n• Advertência verbal"},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"Ausência superior a 3 dias sem aviso pode resultar em rebaixamento ou desligamento.","n":"","t":"Todo policial tem o direito de apelar de uma punição, apresentando sua defesa à administração.","p":", apresentando sua defesa à administração."},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"CONDUTA OOC E ROLEPLAY","n":"","t":"É proibido misturar IC e OOC.\n(Ex.: “bugou”, “vou reiniciar”, “me matou sem motivo”, “tô gravando”, “vou chamar adm”).\nPunição: 30 minutos de cadeia ( OOC - 3.17 )","p":"30 minutos de cadeia ( OOC - 3.17 )"},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"CONDUTA OOC E ROLEPLAY","n":"","t":"Respeite sempre os jogadores e o Roleplay.","p":""},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"CONDUTA OOC E ROLEPLAY","n":"","t":"Evite metagaming, combat logging e powergaming.","p":""},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"CONDUTA OOC E ROLEPLAY","n":"","t":"O descumprimento dessas regras resultará em punições internas e administrativas.","p":""},{"g":"Regras das organizações","b":"REGRAS DE PATRULHA E OPERAÇÕES","s":"CONDUTA OOC E ROLEPLAY","n":"","t":"A Polícia é uma instituição de honra.\nCada membro representa a lei, a ordem e o respeito ao servidor.\nSirva com disciplina, coragem e responsabilidade.\nTurno de trabalho: das 17:00 às 02:00.\nDurante este período, todos os funcionários devem estar de serviço e uniformizados.\nNota importante:\nO General e os Coronéis da organização têm o direito de relatar à administração ou aplicar ações disciplinares de forma independente ao detectar um infrator.\nLimite de líderes: 7 coronéis + Líder ( total de 8).","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 1 — DISPOSIÇÕES GERAIS","n":"1.1","t":"Todos os funcionários do exército devem conhecer e cumprir esta carta.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 1 — DISPOSIÇÕES GERAIS","n":"1.2","t":"Para violações dos artigos das regras, os funcionários podem sofrer as seguintes ações disciplinares: advertência, repreensão, demissão ou demissão com inclusão na lista negra da organização.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 1 — DISPOSIÇÕES GERAIS","n":"1.3","t":"Todo funcionário tem o direito de apelar de uma ação disciplinar.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 1 — DISPOSIÇÕES GERAIS","n":"1.4","t":"Durante o horário de trabalho, todos os funcionários devem estar uniformizados. É possível solicitar folga ao General ou Coronéis da organização.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 2 — PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO EXÉRCITO","n":"2.1","t":"Conhecer e cumprir as leis do estado, a carta da organização e garantir sua aplicação.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 2 — PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO EXÉRCITO","n":"2.2","t":"Proteger a vida dos cidadãos por quaisquer meios necessários.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 2 — PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO EXÉRCITO","n":"2.3","t":"Obedecer às ordens e solicitações de oficiais superiores sem questionar, desde que dentro da lei.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 2 — PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO EXÉRCITO","n":"2.4","t":"Observar a cadeia de comando.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 2 — PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO EXÉRCITO","n":"2.5","t":"Seguir a ordem interna da organização.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 2 — PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO EXÉRCITO","n":"2.6","t":"Ser educado e diplomático ao se comunicar com os cidadãos.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 2 — PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO EXÉRCITO","n":"2.7","t":"Em caso de dano intencional ou acidental, o funcionário deve reparar o veículo de trabalho.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 2 — PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO EXÉRCITO","n":"2.8","t":"Os soldados devem conhecer os oficiais superiores pelo rosto e nome.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 2 — PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO EXÉRCITO","n":"2.9","t":"Proteger os bens e valores do exército.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 2 — PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO EXÉRCITO","n":"2.10","t":"Apresentar documentos ao oficial de serviço nos postos de controle.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 2 — PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO EXÉRCITO","n":"2.11","t":"Nos postos de controle, verificar os documentos de todos os civis que chegarem.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 2 — PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO EXÉRCITO","n":"2.12","t":"Antes de verificar documentos, os soldados devem se apresentar.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 2 — PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO EXÉRCITO","n":"2.13","t":"Guardar o território do exército diariamente. A distribuição das áreas de serviço é feita pelo adjunto ou líder.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 3 — OS FUNCIONÁRIOS DO EXÉRCITO PODEM","n":"3.1","t":"Atirar em civis que entrem ilegalmente no território do exército.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 3 — OS FUNCIONÁRIOS DO EXÉRCITO PODEM","n":"3.2","t":"Ajudar outras facções governamentais durante eventos.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 3 — OS FUNCIONÁRIOS DO EXÉRCITO PODEM","n":"3.3","t":"Verificar documentos de identidade de civis e funcionários.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 3 — OS FUNCIONÁRIOS DO EXÉRCITO PODEM","n":"3.4","t":"Fazer perguntas aos oficiais superiores.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 3 — OS FUNCIONÁRIOS DO EXÉRCITO PODEM","n":"3.5","t":"Treinar tiro fora do horário de trabalho.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 3 — OS FUNCIONÁRIOS DO EXÉRCITO PODEM","n":"3.6","t":"Solicitar assistência via rádio.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 3 — OS FUNCIONÁRIOS DO EXÉRCITO PODEM","n":"3.7","t":"Atirar em civis que apontem arma para outro civil ou policial.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 3 — OS FUNCIONÁRIOS DO EXÉRCITO PODEM","n":"3.8","t":"Tirar folga ou férias com aprovação do General ou Coronéis (por até duas semanas).","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 3 — OS FUNCIONÁRIOS DO EXÉRCITO PODEM","n":"3.9","t":"Bloquear estradas para prevenir crimes (ex.: entrega de guaraná por máfia).","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 3 — OS FUNCIONÁRIOS DO EXÉRCITO PODEM","n":"3.10","t":"Colidir ou atirar em veículos para prevenir crimes (ex.: entrega de guaraná por máfia).","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 3 — OS FUNCIONÁRIOS DO EXÉRCITO PODEM","n":"3.11","t":"Transportar e armazenar armas em qualquer local.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 3 — OS FUNCIONÁRIOS DO EXÉRCITO PODEM","n":"3.12","t":"Estacionar veículos pessoais no território da organização.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.1","t":"Vender ou perder uniformes militares.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.2","t":"Vender qualquer propriedade do governo.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.3","t":"Pedir promoções de patente ou posição.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.4","t":"Sair da base sem permissão.\nNota: sair da base sem relatar é considerado ausência não autorizada.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.5","t":"Ficar sozinho em favelas sem necessidade.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.6","t":"Causar danos físicos a colegas, civis, funcionários ou propriedades sem motivo.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.7","t":"Enganar soldados ou civis.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.8","t":"Discutir, ignorar ou questionar ordens de oficiais superiores.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.9","t":"Usar linguagem obscena, insultar ou humilhar alguém.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.10","t":"Colaborar com grupos criminosos ou máfias.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.11","t":"Abusar da autoridade.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.12","t":"Usar máscara sem necessidade.\nNota: o uso deve ser relatado via rádio com o motivo.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.13","t":"Acompanhar civis ou membros de gangues na base.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.14","t":"Resolver assuntos pessoais durante o trabalho.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.15","t":"Possuir ou usar drogas ou álcool durante o serviço.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.16","t":"Usar veículos de serviço para fins pessoais.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.17","t":"Qualquer comportamento inadequado é proibido.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.18","t":"Fazer quest durante o trabalho.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.19","t":"Usar o megafone indevidamente.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.20","t":"Trabalhar em empregos secundários durante o serviço ou enquanto estiver uniformizado.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.21","t":"Aceitar subornos.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.22","t":"Usar armas para fins pessoais.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.23","t":"Ocupar ou sair de postos sem relatórios via rádio.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.24","t":"Alterar ou escolher postos sem autorização.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 4 — É PROIBIDO AOS FUNCIONÁRIOS DO EXÉRCITO","n":"4.25","t":"Usar o rádio e o chat do departamento para fins não relacionados ao trabalho.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 5 — REGRAS De FORMAÇÃO","n":"5.1","t":"O tempo de formação é exatamente 5 minutos.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 5 — REGRAS De FORMAÇÃO","n":"5.2","t":"É proibido usar gestos na formação. Exceção: levantar a mão.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 5 — REGRAS De FORMAÇÃO","n":"5.3","t":"Quebrar a disciplina durante a formação é proibido.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 5 — REGRAS De FORMAÇÃO","n":"5.4","t":"Usar o rádio na formação é proibido.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 5 — REGRAS De FORMAÇÃO","n":"5.5","t":"Conversar na formação é proibido (IC/Whisper).","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 5 — REGRAS De FORMAÇÃO","n":"5.6","t":"Usar telefone na formação é proibido.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 5 — REGRAS De FORMAÇÃO","n":"5.7","t":"Segurar ou usar armas na formação é proibido.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 6 — REGRAS DE COMUNICAÇÃO E SUBORDINAÇÃO","n":"6.1","t":"Os funcionários do exército devem comunicar-se educadamente com todos os cidadãos, independentemente do status.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"CAPÍTULO 6 — REGRAS DE COMUNICAÇÃO E SUBORDINAÇÃO","n":"6.2","t":"Assuntos pessoais, insultos e brigas no rádio ou no chat do departamento são proibidos.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"Capítulo 7 — Horário de Trabalho","n":"7.1","t":"Horas mínimas semanais no jogo para os funcionários do exército: 7 horas.","p":""},{"g":"Regras das organizações","b":"REGRAS DO EXÉRCITO","s":"Capítulo 7 — Horário de Trabalho","n":"7.2","t":"Máximo de ausência do jogo: 3 dias.\nO turno de trabalho é das 08:00 às 22:00, durante este período cada funcionário deve estar de serviço e com uniforme. O intervalo é das 12:00 às 13:00.\nO Diretor e os Vices da organização têm o direito de reportar à administração ou aplicar medidas disciplinares de forma independente ao detectar um infrator.\nVale ressaltar que, dentro do hospital, haverá um número limitado de cargos superiores, sendo: 1 Diretor e 6 Vices.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 1. DISPOSIÇÕES GERAIS","n":"1.1","t":"Todos os funcionários do hospital devem conhecer e seguir estas regras.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 1. DISPOSIÇÕES GERAIS","n":"1.2","t":"Por violação dos artigos descritos nas regras, os funcionários podem enfrentar as seguintes penalidades: aviso / repreensão / demissão / demissão com lista negra da organização.","p":"aviso / repreensão / demissão / demissão com lista negra da organização."},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 1. DISPOSIÇÕES GERAIS","n":"1.3","t":"Todo funcionário tem o direito de apelar de sua punição.","p":"."},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 1. DISPOSIÇÕES GERAIS","n":"1.4","t":"Durante o horário de trabalho, todos os funcionários devem estar uniformizados. Pode-se solicitar folga aos líderes ou adjuntos da organização.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 1. DISPOSIÇÕES GERAIS","n":"1.5","t":"proibido utilizar o hospital como fuga estratégica para evitar ações RP.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 1. DISPOSIÇÕES GERAIS","n":"1.6","t":"É proibido acampar (ficar esperando para matar ou sequestrar alguém).","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 1. DISPOSIÇÕES GERAIS","n":"1.7","t":"É proibido qualquer tipo de meta-gaming ou power-gaming dentro das dependências.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 1. DISPOSIÇÕES GERAIS","n":"1.8","t":"É proibido iniciar qualquer tipo de agressão física ou verbal dentro do hospital.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 1. DISPOSIÇÕES GERAIS","n":"1.9","t":"É proibido sacar armas dentro das dependências do hospital.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 1. DISPOSIÇÕES GERAIS","n":"1.20","t":"É proibido realizar assaltos, sequestros ou qualquer ação criminosa dentro do hospital.\nO hospital é considerado área neutra, salvo situações previamente autorizadas pela administração.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 1. DISPOSIÇÕES GERAIS","n":"1.21","t":"É proibido utilizar o hospital para obter vantagens indevidas em ações de RP, como fugir de confrontos, esconder-se de perseguições ou evitar consequências de ações criminosas.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 1. DISPOSIÇÕES GERAIS","n":"1.22","t":"É proibido realizar qualquer tipo de ação criminosa, brigas, ameaças, disparos de arma de fogo ou causar desordem dentro das dependências do hospital.\nO descumprimento desta regra será considerado quebra de RP e poderá resultar em punições administrativas conforme a gravidade da infração.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 2. PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO HOSPITAL","n":"2.1","t":"Seguir as leis do estado e o estatuto da organização, bem como garantir seu cumprimento.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 2. PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO HOSPITAL","n":"2.2","t":"Proteger a vida dos cidadãos por todos os meios e métodos.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 2. PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO HOSPITAL","n":"2.3","t":"Seguir a cadeia de comando no hospital e além.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 2. PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO HOSPITAL","n":"2.4","t":"Seguir sem questionar as ordens/requisitos de superiores dentro da lei.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 2. PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO HOSPITAL","n":"2.5","t":"O profissional de saúde deve fornecer assistência médica a quem precisar, independentemente do status social, posição financeira ou filiação racial/religiosa/política.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 2. PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO HOSPITAL","n":"2.6","t":"Responder imediatamente às chamadas de ambulância e prestar primeiros socorros às vítimas.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 2. PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO HOSPITAL","n":"2.7","t":"Ser educado e cortês ao comunicar-se com os cidadãos.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 2. PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO HOSPITAL","n":"2.8","t":"Seguir os procedimentos internos da organização.\nMédicos devem manter postura profissional durante todo o atendimento.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 2. PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO HOSPITAL","n":"2.9","t":"É proibido abandonar atendimento em andamento sem justificativa.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 2. PRINCIPAIS DEVERES DOS FUNCIONÁRIOS DO HOSPITAL","n":"2.10","t":"É obrigatório seguir os protocolos médicos definidos pela equipe de saúde.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 3. FUNCIONÁRIOS DO HOSPITAL PODEM","n":"3.1","t":"Solicitar que qualquer cidadão deixe o prédio ou território se representar uma ameaça.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 3. FUNCIONÁRIOS DO HOSPITAL PODEM","n":"3.2","t":"Solicitar assistência via rádio.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 3. FUNCIONÁRIOS DO HOSPITAL PODEM","n":"3.3","t":"Fazer perguntas aos superiores.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 3. FUNCIONÁRIOS DO HOSPITAL PODEM","n":"3.4","t":"Atender chamadas de ambulância em dupla.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 3. FUNCIONÁRIOS DO HOSPITAL PODEM","n":"3.5","t":"Portar armas com licença.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 3. FUNCIONÁRIOS DO HOSPITAL PODEM","n":"3.6","t":"Recusar tratamento a pacientes que sejam grosseiros ou se comportem inadequadamente.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 3. FUNCIONÁRIOS DO HOSPITAL PODEM","n":"3.7","t":"Solicitar folga ou férias coordenadas com o líder ou adjunto da organização (até duas semanas).","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 3. FUNCIONÁRIOS DO HOSPITAL PODEM","n":"3.8","t":"Estacionar veículos pessoais na área de estacionamento da organização.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 4. FUNCIONÁRIOS DO HOSPITAL NÃO PODEM","n":"4.1","t":"Usar veículos de serviço para fins pessoais.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 4. FUNCIONÁRIOS DO HOSPITAL NÃO PODEM","n":"4.2","t":"Consumir álcool durante o expediente.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 4. FUNCIONÁRIOS DO HOSPITAL NÃO PODEM","n":"4.3","t":"Usar e armazenar substâncias narcóticas.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 4. FUNCIONÁRIOS DO HOSPITAL NÃO PODEM","n":"4.4","t":"Quebrar leis.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 4. FUNCIONÁRIOS DO HOSPITAL NÃO PODEM","n":"4.5","t":"Comportamento inadequado.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 4. FUNCIONÁRIOS DO HOSPITAL NÃO PODEM","n":"4.6","t":"Visitar outros hospitais sem permissão da liderança do hospital visitado.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 4. FUNCIONÁRIOS DO HOSPITAL NÃO PODEM","n":"4.7","t":"Recusar tratamento a cidadãos que chegam ao hospital. Exceção - pacientes inadequados.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 4. FUNCIONÁRIOS DO HOSPITAL NÃO PODEM","n":"4.8","t":"Bater ou atirar em colegas.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 4. FUNCIONÁRIOS DO HOSPITAL NÃO PODEM","n":"4.9","t":"Estar em cassinos ou outros locais de entretenimento com uniforme durante o expediente.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 4. FUNCIONÁRIOS DO HOSPITAL NÃO PODEM","n":"4.10","t":"Ignorar/desobedecer ordens de superiores.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 4. FUNCIONÁRIOS DO HOSPITAL NÃO PODEM","n":"4.11","t":"Ter conexões com organizações criminosas.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 4. FUNCIONÁRIOS DO HOSPITAL NÃO PODEM","n":"4.12","t":"Trabalhar em empregos paralelos ou outros trabalhos durante o expediente ou com uniforme.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 4. FUNCIONÁRIOS DO HOSPITAL NÃO PODEM","n":"4.13","t":"Usar veículo de serviço para fins pessoais.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 4. FUNCIONÁRIOS DO HOSPITAL NÃO PODEM","n":"4.14","t":"Usar rádio ou chat do departamento para assuntos não relacionados ao trabalho, incluindo tentar vender itens, anunciar negócios etc.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 4. FUNCIONÁRIOS DO HOSPITAL NÃO PODEM","n":"4.15","t":"Pedir bônus ou promoção de cargo.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 4. FUNCIONÁRIOS DO HOSPITAL NÃO PODEM","n":"4.16","t":"Realizar questões durante o expediente.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 5. REGRAS DE COMUNICAÇÃO. CADEIA DE COMANDO","n":"5.1","t":"O funcionário do hospital deve comunicar-se de forma educada com qualquer cidadão, independentemente de seu status financeiro ou posição social.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 5. REGRAS DE COMUNICAÇÃO. CADEIA DE COMANDO","n":"5.2","t":"Conversas pessoais, insultos e esclarecimentos de relacionamentos no rádio e chat do departamento são proibidos.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 6. HORÁRIO DE TRABALHO","n":"6.1","t":"Horas mínimas exigidas no jogo para funcionário do hospital por semana: 8 horas.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 6. HORÁRIO DE TRABALHO","n":"6.2","t":"Período máximo de ausência no jogo para funcionário do hospital: 3 dias.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 7. PACIENTES","n":"7.1","t":"É obrigatório valorizar a própria vida (VL - Valorização da Vida).","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 7. PACIENTES","n":"7.2","t":"É proibido levantar ou sair correndo imediatamente após ser reanimado sem interpretação adequada da cena.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 7. PACIENTES","n":"7.3","t":"É obrigatório respeitar o tempo de recuperação estipulado pela equipe médica.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 7. PACIENTES","n":"7.4","t":"É obrigatório respeitar a fila e a ordem de atendimento.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 7. PACIENTES","n":"7.5","t":"É proibido atrapalhar o atendimento médico com brincadeiras, provocações ou ações sem sentido (anti-RP).","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 7. PACIENTES","n":"7.6","t":"É proibido forçar atendimento imediato sem justificativa RP plausível.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 7. PACIENTES","n":"7.7","t":"É obrigatório que médicos e pacientes realizem o RP completo durante os atendimentos hospitalares, mantendo coerência com a situação da ação.\nPacientes devem interpretar dores, ferimentos, quedas e reações aos procedimentos médicos de forma realista, evitando levantar ou agir normalmente sem a devida interpretação.\nMédicos devem utilizar comandos e ações médicas de forma coerente com o atendimento, descrevendo procedimentos e mantendo a imersão do RP.\nLembrando que o servidor é voltado à geração de Roleplay, portanto todas as situações médicas devem ser interpretadas de forma fiel e completa.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 8. POLÍCIAS","n":"8.1","t":"É proibido entrar em hospital em perseguição ativa (salvo se a regra do servidor permitir).","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 8. POLÍCIAS","n":"8.2","t":"É proibido efetuar disparos dentro do hospital.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 8. POLÍCIAS","n":"8.3","t":"É obrigatório manter auxílio de efetivo policial na porta do hospital durante ações ou movimentações relevantes.\nDeverá haver, no mínimo, 2 (dois) oficiais presentes e ativos no local, realizando a segurança da área.\nA ausência de efetivo mínimo ou a inatividade dos oficiais designados será considerada falha operacional. Nesses casos, o chefe da corporação responsável poderá receber 1 advertência direta (1/3).","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 9. ÁREA PÚBLICA DO HOSPITAL","n":"9.1","t":"O hospital é considerado uma área pública. Portanto, jogadores podem permanecer e circular livremente no local, desde que não estejam cometendo qualquer ato de arruaça, perturbação da paz ou quebra de regra.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 9. ÁREA PÚBLICA DO HOSPITAL","n":"9.2","t":"É proibido retirar ou expulsar jogadores que estejam dentro do hospital sem que tenham cometido alguma infração ou causado desordem no local. A permanência será permitida enquanto houver respeito à ordem, ao ambiente hospitalar e às normas do servidor.","p":""},{"g":"Regras das organizações","b":"REGRAS DO HOSPITAL","s":"CAPÍTULO 10. AUTORIDADE MÉDICA E CIRCULAÇÃO DE VTR","n":"10.1","t":"É permitido aos paramédicos circularem por qualquer local do mapa em VTRs para prestar auxílio médico. Nenhum jogador deve impedir, ordenar ou restringir o deslocamento dos paramédicos durante o exercício de suas funções.\nO hospital possui autoridade para acessar locais públicos e privados exclusivamente para realização de atendimentos médicos, desde que haja um jogador necessitando de socorro.\nCaso o paciente esteja desrespeitando a equipe médica, causando desordem ou quebrando regras durante o atendimento, ficará a critério do médico decidir prestar ou não o auxílio naquele momento.\nQualquer tentativa de impedir, interferir ou atrapalhar o trabalho da equipe médica será considerada ato de Anti-RP, sujeito às devidas punições administrativas.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Disposições Gerais","n":"1.1","t":"Estas regras são obrigatórias para todos os funcionários da facção de mídia Rio News.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Disposições Gerais","n":"1.2","t":"As regras podem ser alteradas, atualizadas ou complementadas pela liderança da facção a qualquer momento.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Disposições Gerais","n":"1.3","t":"O descumprimento de qualquer item poderá resultar em advertência, suspensão ou demissão do cargo, conforme a gravidade da infração.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Disposições Gerais","n":"1.4","t":"A ignorância das regras não isenta o funcionário de sua responsabilidade.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Princípios Gerais da Mídia de Massa","n":"2.1","t":"A mídia é responsável por divulgar anúncios de forma clara, objetiva e fiel ao conteúdo enviado pelo jogador.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Princípios Gerais da Mídia de Massa","n":"2.2","t":"É proibido alterar o sentido original do anúncio sob qualquer circunstância.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Princípios Gerais da Mídia de Massa","n":"2.3","t":"Todos os anúncios devem ser editados obrigatoriamente em português e com ortografia correta.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Princípios Gerais da Mídia de Massa","n":"2.4","t":"É proibido adicionar tags, símbolos ou caracteres extras antes do início do anúncio.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Princípios Gerais da Mídia de Massa","n":"2.5","t":"O editor deve manter postura profissional, evitando gírias excessivas, abreviações confusas ou erros gramaticais.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Princípios Gerais da Mídia de Massa","n":"2.5","t":"Limite de líderes: 6 Edito Chefe + Líder ( total de 7).","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Estrutura Obrigatória dos Anúncios","n":"3.1","t":"Todo anúncio deve seguir a padronização abaixo:\nCompra: finalizar com “Orçamento”.\nVenda: finalizar com “Preço”.\nTroca: finalizar com “Pagamento adicional”.\nExemplos:\n✓ Casa à venda em Turim. Preço: 2 milhões.\n✓ Comprarei uma casa em Turim. Orçamento: 4 milhões.\n✓ Trocarei uma casa em Turim por um carro esportivo.\nPagamento adicional: negociável.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Formatação de Valores","n":"4.1","t":"Valores podem ser escritos com pontos separando milhares ou utilizando abreviações (mil, milhão, bilhão).","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Formatação de Valores","n":"4.2","t":"É obrigatório utilizar a formatação correta de valores quando informados.\nExemplos:\n✗ Vou comprar uma casa em Turim. 14 mil.\n✓ Vou comprar uma casa em Turim. Orçamento: R$ 14.000.000.\n✓ Vou comprar uma casa em Turim. Orçamento: 14 milhões.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Ausência de Informações no Anúncio","n":"5.1","t":"Caso o anúncio não informe valores, deve-se padronizar da seguinte forma:\nVenda sem valor: “Preço: negociável”.\nCompra sem valor: “Orçamento: grátis”.\nTroca sem valor: “Pagamento adicional: negociável\"\nExemplos:\n✓ Casa à venda em Turim. Preço: negociável.\n✓ Comprarei uma casa em Turim. Orçamento: grátis.\n✓ Trocarei um carro esportivo por uma mansão. Pagamento adicional: negociável.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Abreviações Permitidas","n":"6.1","t":"É permitido utilizar abreviações padronizadas, mas não é obrigatório.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Abreviações Permitidas","n":"6.2","t":"Abreviações aceitas:\na/c – acessório\nb/z – negócios/empresa\na/m – automóvel\ng/m – caminhão\nm/c – motocicleta\nv/s – bicicleta\nr/s – recurso\ns/o – relacionamento sério\nd/t – elemento de afinação\nt/s – veículo\no/p – costura de roupas (pele)\nExemplos:\n✓ Vou comprar um carro BMW. Orçamento: gratuito.\n✓ Venda de negócio de lanchonete em Turim. Preço: negociável.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Integridade do Conteúdo","n":"7.1","t":"É proibido modificar o conteúdo original do anúncio enviado pelo jogador.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Integridade do Conteúdo","n":"7.2","t":"O editor deve apenas corrigir ortografia, padronizar e organizar o texto, sem alterar o sentido.\nExemplo de violação:\nJogador envia: “Vendo BMW”\nEditor publica: “Vou comprar um BMW.\nOrçamento: gratuito.”","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Conteúdos Especiais e Adaptações","n":"8.1","t":"É proibido anúncios que mencionem plataformas externas (Whatsapp, Skype, Instagram, outros que não condiz da nossa plataforma oficial Discord),","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Conteúdos Especiais e Adaptações","n":"8.2","t":"Anúncios relacionados a facções são permitidos, porém devem ser adaptados para termos neutros, como clubes esportivos.\nExemplo:\n✗ Venda de casa perto da facção Vagos.\n✓ Vendo casa perto do terreno da máfia Vagos. Preço: negociável.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Proibições Gerais","n":"9.1","t":"É proibido anunciar compra ou venda de:\n• Drogas\n• Armas\n• Munições","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Proibições Gerais","n":"9.2","t":"Caso o anúncio viole regras, deve ser rejeitado com justificativa clara.\nExemplo:\nAnúncio: “Comprarei armas”\nResposta: “PRO | Venda de armas proibida”.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Proibições Gerais","n":"9.3","t":"É proibido listar vários bens no mesmo anúncio. Cada anúncio deve conter apenas:\nUm veículo, OU\nUma casa, OU\nUm acessório, OU\nUm recurso.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Regras de Redução e Organização","n":"10.1","t":"É permitido abreviar o nome da cidade somente se o anúncio for muito extenso.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Regras de Redução e Organização","n":"10.2","t":"O texto deve ser claro, organizado e sem excesso de informações desnecessárias.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Trocas e Negociações","n":"11.1","t":"Trocas são permitidas, desde que estejam claramente descritas e com pagamento adicional especificado quando houver.\nExemplo:\n✓ Trocarei uma casa em Turim por um Bugatti Divo. Pagamento adicional: 5 milhões.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Penalidades","n":"12.1","t":"A violação de qualquer regra poderá resultar nas seguintes punições, conforme a regra cometida da infração:\nAdvertência verbal ou escrita no líder da organização;\nAviso 1/3 aplicado a organização, caso atinja 3/3 o líder da organização será desligado automaticamente;\nDemissão da facção de mídia.","p":""},{"g":"Regras das organizações","b":"REGRAS DA FACÇÃO MÍDIA – RIO NEWS (MÍDIA DE MASSA)","s":"Penalidades","n":"12.2","t":"O funcionário que reincidir em erros gramaticais, alteração de sentido do anúncio ou descumprimento de padrões poderá ser removido imediatamente da função.","p":""},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Disposições Gerais","n":"1.1","t":"Cada membro da facção deve conhecer e seguir todas as regras.","p":""},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Disposições Gerais","n":"1.2","t":"A violação de qualquer regra pode resultar em punição .\nPunição: 1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente.","p":".\nPunição: 1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente."},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras Gerais da Gangue","n":"2.1","t":"É proibido matar qualquer jogador sem diálogo RolePlay (RP) prévio e motivo válido.\nExceção: provocação direta que justifique reação imediata.\nPunição: 60 minutos de cadeia ( DM - 4.6 )","p":"60 minutos de cadeia ( DM - 4.6 )"},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras Gerais da Gangue","n":"2.2","t":"Todas as facções são consideradas automaticamente hostis entre si.","p":""},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras Gerais da Gangue","n":"2.3","t":"É proibido matar jogadores pacíficos no spawn das facções sem diálogo ou provocação válida em RP.\nPunição: 60 minutos de cadeia ( SK - 4.8 )","p":"60 minutos de cadeia ( SK - 4.8 )"},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras Gerais da Gangue","n":"2.4","t":"Ao matar um membro de facção rival, é obrigatório possuir motivo válido e realizar um diálogo RP mínimo (várias linhas) revelando a motivação.\nExceção: ações de captura de território.","p":""},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras Gerais da Gangue","n":"2.5","t":"A organização deve manter no mínimo 20 membros online diariamente entre 15:00 e 21:00.\nPunição: Caso a facção não esteja com efetivo exigido, 1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente.","p":"Caso a facção não esteja com efetivo exigido, 1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente."},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras Gerais da Gangue","n":"2.6","t":"É proibido utilizar linguagem obscena ou insultos no rádio da gangue.\nPunição: Desligamento da organização por descumprimento","p":"Desligamento da organização por descumprimento"},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras Gerais da Gangue","n":"2.7","t":"É proibido cooperar com facções governamentais durante eventos.\nPunição: 1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente.","p":"1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente."},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras Gerais da Gangue","n":"2.8","t":"É proibido realizar PVP, agredir, atirar ou matar membros da própria facção.\nPunição: desligamento da organização por descumprimento, caso de evidência apresentada ao suporte, 60 minutos de cadeia ( TK -  4.9 )","p":"desligamento da organização por descumprimento, caso de evidência apresentada ao suporte, 60 minutos de cadeia ( TK -  4.9 )"},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras Gerais da Gangue","n":"2.9","t":"Os membros devem obedecer às ordens da liderança superior (Líder e Vice-Líder).\nPunição: Desligamento da organização por descumprimento","p":"Desligamento da organização por descumprimento"},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras Gerais da Gangue","n":"2.10","t":"É proibido solicitar promoção de patente diretamente à liderança.\nPunição: Desligamento da organização por descumprimento","p":"Desligamento da organização por descumprimento"},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras Gerais da Gangue","n":"2.11","t":"É proibido cooperar com facções governamentais ou outras facções durante eventos específicos, como:\na) Venda de guaraná;\nb) Entrega de materiais.\nPunição: 1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente.","p":"1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente."},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras de Congelamento da facção","n":"3.1","t":"Cada líder pode aplicar no máximo 3 congelamentos no total durante sua gestão.","p":""},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras de Congelamento da facção","n":"3.2","t":"A duração máxima de cada congelamento é de 3 dias.","p":""},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras de Congelamento da facção","n":"3.3","t":"Deve haver um intervalo mínimo de 3 dias entre cada congelamento solicitado pelo líder.","p":""},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras de Congelamento da facção","n":"3.4","t":"Apenas 1 facção pode estar congelada simultaneamente.","p":""},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras de Congelamento da facção","n":"3.5","t":"Ao assumir a liderança, a facção recebe automaticamente um congelamento inicial de 72 horas para:\na) Recrutamento de membros;\nb) Organização interna;\nc) Preparação de estoque.","p":""},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras de Captura de Território","n":"4.1","t":"É proibido faltar intencionalmente a uma captura de território marcada.\nPunição: 1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente.","p":"1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente."},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras de Captura de Território","n":"4.2","t":"É proibido perder capturas de território deliberadamente.\nPunição: 1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente.","p":"1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente."},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras de Captura de Território","n":"4.3","t":"É proibido cooperar com membros de facção inimigas durante capturas de território.\nPunição: 1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente.","p":"1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente."},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras de Captura de Território","n":"4.4","t":"É proibido interromper animações durante ações de captura de território.\nPunição: 1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente.","p":"1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente."},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Estrutura e Limites","n":"5.1","t":"O limite máximo é de 150 membros por facção.","p":""},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Estrutura e Limites","n":"5.2","t":"A estrutura interna deve conter no máximo:\na) 1 Líder;\nb) 5 Vice-Líderes;\nc) 6 Gerentes.\nPunição: 1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente.","p":"1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente."},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Estrutura e Limites","n":"5.3","t":"Facção com líder inativo por mais de 3 dias sem justificativa perderá a liderança, devendo ser comunicado ao superior pelo servidor.","p":""},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Estrutura e Limites","n":"5.4","t":"Banimentos iguais ou superiores a 3 dias resultam em desligamento automático e reset da facção sem aviso prévio.","p":""},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Conduta e Interações","n":"6.1","t":"É proibido provocar funcionários de organizações governamentais.\nPunição: Prisão de 60 minutos por Forçar RP - 3.23","p":"Prisão de 60 minutos por Forçar RP - 3.23"},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Conduta e Interações","n":"6.2","t":"É proibido ficar AFK durante guerra de território.\nPunição: Chute - 2.2","p":"Chute - 2.2"},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Conduta e Interações","n":"6.3","t":"É proibido realizar ações com famílias.\nPunição: 1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente.","p":"1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente."},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Conduta e Interações","n":"6.4","t":"É proibido realizar alianças com famílias externas à facção.\nPunição: 1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente.","p":"1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente."},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Conduta e Interações","n":"6.5","t":"É proibido qualquer tipo de relacionamento ou envolvimento entre membros de facções rivais.\nPunição: 1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente.","p":"1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente."},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Conduta e Interações","n":"6.6","t":"Membros que desejarem sair de uma facção/organização/corporação deverão:\na) Aguardar 24 horas (1 dias) para entrar em outra;\nb) Para retornar à mesma facção, aguardar 48 horas (2 dias).","p":""},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Conduta e Interações","n":"6.7","t":"É proibido desrespeitar a hierarquia da facção.\nPunição: Advertência verbal pelo lider","p":"Advertência verbal pelo lider"},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Conduta e Interações","n":"6.8","t":"É proibido estar sem uniforme da facção dentro das favelas.\nPunição: Chute sem fardamento 2.2","p":"Chute sem fardamento 2.2"},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras de Ações e Conflitos","n":"7.1","t":"Todas as invasões e pacificações devem ser obrigatoriamente agendadas pelo suporte.\nPunição: INA - 4.21","p":"INA - 4.21"},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras de Ações e Conflitos","n":"7.2","t":"Invasões podem ser realizadas apenas 1 vez por dia (vida real) e devem ter no mínimo 4 membros online de cada lado na cidade.\nPunição: Caso de descumprimento, 60 minutos de cadeia ( FAIL - 4.22 )","p":"Caso de descumprimento, 60 minutos de cadeia ( FAIL - 4.22 )"},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras de Ações e Conflitos","n":"7.3","t":"Após o início de pacificação policial em favelas ou locais de busca/apreensão, é proibida a entrada de reforços de ambos os lados.\nPunição: 1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente.","p":"1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente."},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras de Ações e Conflitos","n":"7.4","t":"Ao morrer durante uma ação, o jogador deve aguardar o término para receber atendimento médico.","p":""},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras de Ações e Conflitos","n":"7.5","t":"É extremamente proibido falar quando estiver “morto”.\nPunição: Mute de 40 minutos por “Desmaiado”.  3.26","p":"Mute de 40 minutos por “Desmaiado”.  3.26"},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras de Ações e Conflitos","n":"7.6","t":"Nenhum tipo de ação de rua pode juntar múltiplas equipes contra a polícia; apenas 1 equipe pode participar da ação.\nPunição: 60 minutos de cadeia ( FAIL- 4.22 )","p":"60 minutos de cadeia ( FAIL- 4.22 )"},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras de Ações e Conflitos","n":"7.7","t":"Todos os criminosos devem prezar pela própria vida, sendo proibido ir à polícia ou ao exército sem aviso prévio.\nPunição: 40 minutos de cadeia ( SAAV - 4.10 )","p":"40 minutos de cadeia ( SAAV - 4.10 )"},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Combate, PVP e Territórios","n":"8.1","t":"É proibido PVP em área de base.\nPunição: 60 minutos de cadeia ( RDM - 4.2 )","p":"60 minutos de cadeia ( RDM - 4.2 )"},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Combate, PVP e Territórios","n":"8.2","t":"É proibido entrar no território de outras facções para forçar PVP.\nPunição: 60 minutos de cadeia ( RDM - 4.2 )","p":"60 minutos de cadeia ( RDM - 4.2 )"},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Combate, PVP e Territórios","n":"8.3","t":"Enquanto houver apenas 2 facções na cidade,  proibido qualquer tipo de aliança entre elas.\nPunição: 1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente.","p":"1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente."},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Combate, PVP e Territórios","n":"8.4","t":"É proibido uma facção atrapalhar a outra durante ações de assalto ou roubo.\nPunição: 60 minutos de cadeia ( AAP - 4.17 )","p":"60 minutos de cadeia ( AAP - 4.17 )"},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras de Crimes e Bens","n":"9.1","t":"É extremamente proibido obrigar a vítima a transferir dinheiro ou bens, inclusive levá-la ao banco para sacar valores da conta.\nPunição: 1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente.","p":"1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente."},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras de Crimes e Bens","n":"9.2","t":"É proibido roubar ou furtar viaturas.\nPunição: 1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente.","p":"1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente."},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras de Crimes e Bens","n":"9.3","t":"Suspeitos que iniciem fuga sem possuir nível criminal receberão punição máxima por Forçar RP.\nPunição: 60 minutos de cadeia Forçar RP - 3.23","p":"máxima por Forçar RP.\nPunição: 60 minutos de cadeia Forçar RP - 3.23"},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Regras de Recrutamento","n":"10.1","t":"O recrutamento deve ser realizado apenas in-game ou via Discord oficial das organizações.\nPunição: Advertência verbal\nQuarta-feira\n• 19:00 — Tomada de território\n• 23:00 — Tomada de território\nPremiação: 20k de materiais para o vencedor\nQuinta-feira\n• 19:00 — Tomada de território\n• 23:00 — Tomada de território\nSexta-feira\n• 19:00 — Tomada de território\n• 23:00 — Tomada de território\nPremiação: 20k de materiais para o vencedor\nExplicação\nA premiação foi posicionada no último horário de dias alternados para aumentar a adesão e competitividade, incentivando as facções a se manterem ativas até o horário final, onde a disputa tende a ser mais intensa.\nO pagamento da premiação será realizado obrigatoriamente em até 48h após a ação.","p":"Advertência verbal\nQuarta-feira"},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Disposições Finais","n":"11.1","t":"As facções são proibidas de realizar alianças com famílias que não pertençam oficialmente à facção.\nPunição: 1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente.","p":"1/3 de aviso para a facção. Ao atingir 3/3 avisos, o líder da organização será desligado automaticamente."},{"g":"Regras das organizações","b":"REGRAS DAS FACÇÕES","s":"Disposições Finais","n":"11.2","t":"O descumprimento do limite máximo de membros resultará em advertência verbal ou punição de aviso na facção por descumprimento da regra.","p":"de aviso na facção por descumprimento da regra."},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"1. REQUISITOS DO SEQUESTRO","n":"1.1","t":"É obrigatório haver mais sequestradores do que vítimas, sendo necessário que todos os sequestradores estejam portando arma de fogo.\nPunição: 60 minutos de cadeia — FAIL 4.22","p":"60 minutos de cadeia — FAIL 4.22"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"1. REQUISITOS DO SEQUESTRO","n":"1.2","t":"Apenas facções e máfias estão autorizadas a realizar sequestros. Civis ou organizações não criminosas não podem executar esse tipo de ação.\nPunição: 60 minutos de cadeia — FAIL 4.22","p":"60 minutos de cadeia — FAIL 4.22"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"1. REQUISITOS DO SEQUESTRO","n":"1.3","t":"Todos os sequestradores deverão utilizar máscara durante toda a ação, desde a abordagem até a finalização.\nPunição: 60 minutos de cadeia — FAIL 4.22","p":"60 minutos de cadeia — FAIL 4.22"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"2. INTERFERÊNCIA E IMERSÃO","n":"2.1","t":"É proibido interferir em ações de sequestro nas quais o jogador não esteja diretamente envolvido.\nPunição: 60 minutos de cadeia — AAP 4.17","p":"60 minutos de cadeia — AAP 4.17"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"2. INTERFERÊNCIA E IMERSÃO","n":"2.2","t":"O sequestrado deverá apresentar comportamento compatível com a situação, demonstrando medo, tensão e preocupação diante do risco.\nPunição: 60 minutos de cadeia — FAIL 4.22","p":"60 minutos de cadeia — FAIL 4.22"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"2. INTERFERÊNCIA E IMERSÃO","n":"2.3","t":"É proibido realizar piadas, brincadeiras ou qualquer comportamento que quebre a imersão da ação.\nPunição: 60 minutos de cadeia — FAIL 4.22","p":"60 minutos de cadeia — FAIL 4.22"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"3. COMUNICAÇÃO DO REFÉM","n":"3.1","t":"A partir do momento em que uma arma estiver apontada para a cabeça do personagem, sua comunicação estará automaticamente cortada.","p":""},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"3. COMUNICAÇÃO DO REFÉM","n":"3.2","t":"O sequestrado não poderá utilizar rádio, celular ou qualquer outro meio externo sem autorização dos sequestradores.\nPunição: 40 minutos de cadeia — SAAV 4.10","p":"40 minutos de cadeia — SAAV 4.10"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"3. COMUNICAÇÃO DO REFÉM","n":"3.3","t":"Em situações envolvendo refém, a vítima poderá tentar entrar em contato com familiares ou autoridades para gerar RP, desde que isso seja permitido pelos sequestradores.\nPunição: 40 minutos de cadeia — FORÇAR RP 3.23","p":"40 minutos de cadeia — FORÇAR RP 3.23"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"4. ARMAMENTO E VALORES","n":"4.1","t":"Ações de rua relacionadas ao sequestro poderão ser realizadas utilizando qualquer tipo de arma permitido pelo servidor.","p":""},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"4. ARMAMENTO E VALORES","n":"4.2","t":"Em ações sem sequestro, o valor máximo permitido será de R$ 5.000 por refém envolvido.\nPunição: 60 minutos de cadeia — FAIL 4.22","p":"60 minutos de cadeia — FAIL 4.22"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"4. ARMAMENTO E VALORES","n":"4.3","t":"Em ações com sequestro, o valor máximo permitido será de R$ 8.000 por refém envolvido.\nPunição: 60 minutos de cadeia — FAIL 4.22","p":"60 minutos de cadeia — FAIL 4.22"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"5. DURAÇÃO E HORÁRIO","n":"5.1","t":"Ações que envolvam reféns terão duração máxima de 30 minutos.\nApós esse período, a situação deverá ser finalizada através de liberação, negociação ou outro desfecho coerente de RP.\nPunição: 60 minutos de cadeia — FAIL 4.22","p":"60 minutos de cadeia — FAIL 4.22"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"5. DURAÇÃO E HORÁRIO","n":"5.2","t":"Ações de sequestro somente poderão ocorrer entre 08:00 e 00:00.","p":""},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"5. DURAÇÃO E HORÁRIO","n":"5.3","t":"Deverá ser respeitado um intervalo mínimo de 30 minutos entre uma ação e outra realizada pela mesma organização.\nPunição: 60 minutos de cadeia — FAIL 4.22","p":"60 minutos de cadeia — FAIL 4.22"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"6. IDENTIFICAÇÃO DA AÇÃO","n":"6.1","t":"Os sequestradores deverão anunciar claramente que se trata de uma ação de sequestro.","p":""},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"6. IDENTIFICAÇÃO DA AÇÃO","n":"6.2","t":"O anúncio deverá ser realizado obrigatoriamente por /s ou VOIP, deixando evidente para a vítima que a situação faz parte de uma ação de sequestro.\nPunição: 60 minutos de cadeia — FAIL 4.22\nAs regras abaixo regulamentam o trabalho de Carro Forte, garantindo organização, segurança e coerência durante toda a operação.","p":"60 minutos de cadeia — FAIL 4.22\nAs regras abaixo regulamentam o trabalho de Carro Forte, garantindo organização, segurança e coerência durante toda a operação."},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"7. HORÁRIO DE TRABALHO","n":"7.1","t":"O serviço de Carro Forte deverá ser realizado exclusivamente entre 17:00 e 02:00.","p":""},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"7. HORÁRIO DE TRABALHO","n":"7.2","t":"É proibido realizar entregas, transporte de valores ou abertura do cofre fora do horário permitido.\nPunição: KICK 2.2 — CF FORA DE HORÁRIO","p":"KICK 2.2 — CF FORA DE HORÁRIO"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"8. UNIFORME","n":"8.1","t":"É proibido utilizar máscara durante a execução do trabalho.\nPunição: KICK 2.2 — RETIRE A MÁSCARA","p":"KICK 2.2 — RETIRE A MÁSCARA"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"8. UNIFORME","n":"8.2","t":"Todos os trabalhadores deverão estar obrigatoriamente uniformizados com a vestimenta padrão da empresa.\nPunição: KICK 2.2 — TRABALHO SEM FARDAMENTO","p":"KICK 2.2 — TRABALHO SEM FARDAMENTO"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"8. UNIFORME","n":"8.3","t":"É proibido atuar descaracterizado ou utilizando roupas que não representem a função de Carro Forte.\nPunição: KICK 2.2 — TRABALHO SEM FARDAMENTO","p":"KICK 2.2 — TRABALHO SEM FARDAMENTO"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"9. COMPOSIÇÃO DA EQUIPE","n":"9.1","t":"A operação deverá ser realizada obrigatoriamente com a equipe completa.","p":""},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"9. COMPOSIÇÃO DA EQUIPE","n":"9.2","t":"É necessário possuir 4 trabalhadores para iniciar qualquer operação relacionada ao Carro Forte.","p":""},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"9. COMPOSIÇÃO DA EQUIPE","n":"9.3","t":"É proibido iniciar entregas, deslocamentos ou abertura do cofre com equipe incompleta.\nPunição: KICK 2.2 — CF INCOMPLETO","p":"KICK 2.2 — CF INCOMPLETO"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"10. ESCOLTA","n":"10.1","t":"É permitida escolta de até 8 pessoas, não sendo obrigatório o uso de fardamento pelos integrantes da escolta.","p":""},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"10. ESCOLTA","n":"10.2","t":"Todos os integrantes da escolta deverão estar cientes do plano de ação e atuar de forma coerente com o RP.","p":""},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"10. ESCOLTA","n":"10.3","t":"A escolta deverá atuar exclusivamente na proteção do veículo e da equipe.","p":""},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"10. ESCOLTA","n":"10.4","t":"É proibida qualquer atuação desorganizada ou sem coordenação com o líder da operação.","p":""},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"11. LIDERANÇA E COORDENAÇÃO","n":"11.1","t":"Um líder deverá ser previamente designado para coordenar toda a operação.","p":""},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"11. LIDERANÇA E COORDENAÇÃO","n":"11.2","t":"Compete ao líder:\n«• Organizar rotas e estratégias;\n• Coordenar os integrantes da equipe;\n• Manter contato com a administração quando necessário;\n• Garantir o cumprimento das regras durante toda a operação.»","p":""},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"11. LIDERANÇA E COORDENAÇÃO","n":"11.3","t":"É proibido agir individualmente sem autorização ou sem alinhamento com o líder.\nPunição: O líder poderá remover o jogador da equipe.","p":"O líder poderá remover o jogador da equipe."},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"12. PERDA DE MEMBRO DURANTE A OPERAÇÃO","n":"12.1","t":"Caso um integrante perca a conexão ou saia durante a operação, a equipe deverá aguardar o retorno do jogador no local para dar continuidade ao trabalho.","p":""},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"12. PERDA DE MEMBRO DURANTE A OPERAÇÃO","n":"12.2","t":"Caso a equipe não consiga manter o mínimo de 4 trabalhadores, a operação deverá ser imediatamente interrompida.\nPunição: KICK 2.2 — CF INCOMPLETO","p":"KICK 2.2 — CF INCOMPLETO"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"12. PERDA DE MEMBRO DURANTE A OPERAÇÃO","n":"12.3","t":"É proibido continuar a operação com equipe abaixo do número mínimo exigido.\nPunição: KICK 2.2 — CF INCOMPLETO","p":"KICK 2.2 — CF INCOMPLETO"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"13. FUNCIONAMENTO DO COFRE","n":"13.1","t":"O cofre deverá ser aberto somente durante entregas oficiais e programadas.","p":""},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"13. FUNCIONAMENTO DO COFRE","n":"13.2","t":"Todos os protocolos de segurança deverão ser respeitados durante a abertura.","p":""},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"13. FUNCIONAMENTO DO COFRE","n":"13.3","t":"É proibido tentar abrir o cofre sem a presença de todos os membros necessários da equipe.\nPunição: KICK 2.2 — CF INCOMPLETO","p":"KICK 2.2 — CF INCOMPLETO"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"13. FUNCIONAMENTO DO COFRE","n":"13.4","t":"É proibido abrir o cofre fora de uma entrega oficial ou sem autorização da liderança.\nPunição: O líder deverá remover o membro da equipe, podendo substituí-lo por outro jogador.","p":"O líder deverá remover o membro da equipe, podendo substituí-lo por outro jogador."},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"14. CONDUTA DURANTE O SERVIÇO","n":"14.1","t":"É proibido desviar da rota sem justificativa plausível dentro do RP.\nPunição: KICK 2.2 — USE 3.2","p":"KICK 2.2 — USE 3.2"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"14. CONDUTA DURANTE O SERVIÇO","n":"14.2","t":"É proibido abandonar o veículo ou os valores transportados.\nPunição: KICK 2.2 — CF INCOMPLETO","p":"KICK 2.2 — CF INCOMPLETO"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"14. CONDUTA DURANTE O SERVIÇO","n":"14.3","t":"É proibido utilizar o Carro Forte para fins pessoais ou qualquer atividade que não esteja relacionada ao trabalho.\nPunição: KICK 2.2 — USE 3.2","p":"KICK 2.2 — USE 3.2"},{"g":"Regras de ações e trabalhos","b":"SEQUESTRO","s":"14. CONDUTA DURANTE O SERVIÇO","n":"14.4","t":"Todos os integrantes deverão manter comportamento sério, profissional e compatível com o RP durante o serviço.\nO descumprimento das regras estabelecidas neste documento poderá resultar em punições administrativas, cadeia ou kick, conforme a infração cometida.\nCARRO FORTE:\n« Equipe incompleta → KICK 2.2\nTrabalho fora do horário → KICK 2.2\nTrabalho sem fardamento → KICK 2.2\nUso de máscara → KICK 2.2\nUso indevido do veículo → KICK 2.2»\nSEQUESTRO:\n« Descumprimento das regras → Punição conforme a regra infringida\nInterferência de terceiros → AAP 4.17\nFalta de imersão → FAIL 4.22\nComunicação indevida → SAAV 4.10\nForçar RP → FORÇAR RP 3.23»\nTodos os envolvidos são responsáveis por conhecer e cumprir integralmente as regras apresentadas neste documento.\nO desconhecimento das regras não isenta o jogador de responsabilidade ou de possíveis punições.","p":"conforme a regra infringida\nInterferência de terceiros → AAP 4.17"},{"g":"Regras de invasão e pacificação","b":"REGRAS DE INVASÃO / PACIFICAÇÃO","s":"REGRAS DE INVASÃO / PACIFICAÇÃO","n":"","t":"Nesta apresentação, será explicado de forma clara como funcionam os sistemas de Pacificação e Invasão, suas regras, objetivos e condutas esperadas durante cada ação dentro do servidor.\nO Que É A PACIFICAÇÃO?","p":""},{"g":"Regras de invasão e pacificação","b":"REGRAS DE INVASÃO / PACIFICAÇÃO","s":"REGRAS DE INVASÃO / PACIFICAÇÃO","n":"","t":"A Pacificação é uma ação estratégica realizada por uma organização/facção com o objetivo de controlar, estabilizar ou reduzir conflitos em determinada área dominada por outra facção, priorizando a negociação e a organização do território.\nObjetivos da Pacificação\n• Restabelecer a ordem em áreas conflituosas;\n• Reduzir confrontos excessivos;\n• Assumir o controle territorial de forma organizada;\n• Garantir domínio estratégico sem gerar caos desnecessário.\n• A invasão/pacificação deve ser autorizada pelo suporte em atendimento.","p":""},{"g":"Regras de invasão e pacificação","b":"REGRAS DE INVASÃO / PACIFICAÇÃO","s":"REGRAS DE INVASÃO / PACIFICAÇÃO","n":"","t":"Para garantir organização, equilíbrio e respeito ao Roleplay, foi estabelecida a seguinte diretriz obrigatória:","p":""},{"g":"Regras de invasão e pacificação","b":"REGRAS DE INVASÃO / PACIFICAÇÃO","s":"REGRAS DE INVASÃO / PACIFICAÇÃO","n":"","t":"A invasão ou pacificação somente poderá ser iniciada mediante autorização prévia do Administrador Líder ou do suporte em atendimento.\nDiretrizes de Autorização\nÉ obrigatório solicitar autorização antes de qualquer ação de invasão ou pacificação.\nA solicitação deve ser feita com antecedência, informando:\n• Facção solicitante;\n• Local da ação;\n• Quantidade de membros envolvidos;\n• Horário previsto para início.\nSem autorização, a ação será considerada irregular.\nPunição: Banimento 5 dias ( INA - 4.21 )\nImportante\n• Caso a ação seja iniciada sem autorização, poderá ser cancelada de imediato.\n• Os envolvidos estarão sujeitos às punições de acordo com ação.\n• A autorização garante que a ação ocorra de forma organizada, justa e dentro das regras da ação.\n• Para que se tenha uma invasão/pacificação deverá ter um RP prévio com história e contexto, evidências claras que facilite você pacífica ou invadir.\n• Não é necessário que o número de invasores e defensores seja igual; apenas o líder da facção deve estar online para que a ação ocorra.\n• É permitido realizar invasão de facção ao Exército Brasileiro das 17:00 às 00:00, desde que a ação esteja previamente marcada.\nÉ proibido","p":"Banimento 5 dias ( INA - 4.21 )\nImportante"},{"g":"Regras de invasão e pacificação","b":"REGRAS DE INVASÃO / PACIFICAÇÃO","s":"REGRAS DE INVASÃO / PACIFICAÇÃO","n":"","t":"É proibido famílias invadir o Exército Brasileiro.\n• Após o início da invasão, quem renascer no spawn do local a ser invadido, vier da rua ou sofrer crash, não poderá sair da área de spawn. Caso descumpra, será sujeito à prisão.\nPunição: 60 minutos de cadeia ( AAP - 4.17 )\n• Em ações de invasão ou pacificação, é proibido aliados se ajudarem direta ou indiretamente.\nPunição: 1/3 aviso para facção\n• Não é permitido permanecer nos arredores da organização no momento da invasão, caracterizando apoio externo ou antijogo.\nPunição: 60 minutos de cadeia ( AAP - 4.17 )","p":"60 minutos de cadeia ( AAP - 4.17 )\n• Em ações de invasão ou pacificação, é proibido aliados se ajudarem direta ou indiretamente."},{"g":"Regras de invasão e pacificação","b":"REGRAS DE INVASÃO / PACIFICAÇÃO","s":"REGRAS DE INVASÃO / PACIFICAÇÃO","n":"","t":"POLÍCIA x FACÇÃO x EXÉRCITO x MÁFIA\n• Em caso de vitória da Polícia ou Exército, a facção derrotada ficará inativa por 24 horas. (A partir de 00:00)\n• Em caso de vitória do Exército, a máfia derrotada ficará inativa por 12 horas. (A partir de 00:00)\n• É obrigatório o mínimo de 10 policiais para iniciar a ação.\n• A pacificação deve ser agendada com antecedência mínima de 24 horas, informando data, horário e organizações envolvidas, para análise e autorização do suporte.\n• É proibido o uso de teaser e cassetete durante ações de invasão ou pacificação, sendo permitido apenas o uso de armamentos letais conforme as regras de combate estabelecidas para esse tipo de ação.\nPunição: 60 minutos de cadeia ( FAIL - 4.22 )\nA invasão ao PS é destinada exclusivamente às facções Verdes e Roxos, com o objetivo de realizar o resgate de membros que estejam presos.\nA ação é totalmente livre, não sendo necessário realizar marcação prévia, desde que o resgate aconteça dentro do horário de funcionamento da PF.\n08h às 12h\n13h às 00h\nATENÇÃO:\nÉ expressamente proibido realizar qualquer ação no PS entre 12h e 13h.\nCaso algum jogador seja identificado realizando ações nesse período, poderá ser punido conforme a regra INA – 4.21.\nSegunda-feira: 21h às 22h\nTerça-feira: 21h às 22h\nQuarta-feira: 21h às 22h\nQuinta-feira: 22h às 23h\nSexta-feira: 21h às 22h\nSábado: 22h às 23h\nDomingo: 21h às 22h\nSegunda-feira: Facção Verdes\nTerça-feira: Facção Roxos\nQuarta-feira: Máfia da Colina\nQuinta-feira: Máfia Litoral\nSexta-feira:\n17h – Máfia do Litoral\n19h – Máfia da Colina\nSábado:\n17h – Facção Verdes\n19h – Facção Roxos\nDomingo: Ação livre.\n➤ REGRA DO DIA DE AÇÃO LIVRE:\nAos domingos, às 17h, a primeira facção que chegar ao local do carregamento (CRM) assumirá automaticamente a liderança da ação, tendo o direito de conduzi-la.\nATENÇÃO – PROIBIÇÃO DE CHEGADA ANTECIPADA:\nÉ proibido que qualquer facção ou família chegue antecipadamente ao local do CRM para guardar ou reservar o caixão antes do horário destinado à ação.\nCaso seja identificada alguma facção ou família realizando essa prática antes das 17h, a situação poderá ser considerada FAIL – 4.22, por realização de ação indevida.\nPortanto, todos deverão respeitar o horário estabelecido e chegar ao local somente no horário marcado. A liderança da ação será definida conforme a primeira facção que chegar às 17h.\nFacções Verdes e Roxos: das 17h às 00h.\nAmbas as máfias poderão realizar ações contra o EB no período das 19h às 00h.\nFica estabelecida uma pausa obrigatória das 22h às 23h, durante a qual nenhuma ação contra o EB poderá ser realizada.\nREGRAS DO HORÁRIO DE PAUSA:\nA pausa das 22h às 23h deverá ser respeitada por ambas as máfias, sem exceções.\nEsse intervalo foi estabelecido para garantir um período de descanso entre as ações, permitindo que as máfias reorganizem suas equipes e preparem seus efetivos para possíveis ataques ou confrontos em seus próprios territórios.\nNão será permitido iniciar ou continuar qualquer ação contra o EB durante o horário de pausa.\nCaso uma família realize o roubo de maleta durante uma ação de máfia no EB e conquiste a máfia durante a ausência da outra, a família será punida com reset da máfia + aviso.\nA máfia anterior terá sua máfia devolvida.\nSábado: Pacificação do EB às máfias, das 21h às 22h.\nDomingo e segunda-feira: Pacificação do EB e da PF às facções, das 21h às 00h.\n@here @everyone","p":"60 minutos de cadeia ( FAIL - 4.22 )\nA invasão ao PS é destinada exclusivamente às facções Verdes e Roxos, com o objetivo de realizar o resgate de membros que estejam presos."},{"g":"Regras do jogo","b":"POLÍTICA DE CONTAS DO JOGO","s":"POLÍTICA DE CONTAS DO JOGO","n":"1.1","t":"Ao criar uma conta dentro do nosso projeto, o jogador declara automaticamente que leu, compreendeu e concorda com todas as regras e diretrizes estabelecidas pelos servidores RioRise.\nIsso inclui as regras gerais, específicas de RP, penalidades, condutas proibidas e qualquer atualização futura comunicada pela administração.","p":", condutas proibidas e qualquer atualização futura comunicada pela administração."},{"g":"Regras do jogo","b":"POLÍTICA DE CONTAS DO JOGO","s":"POLÍTICA DE CONTAS DO JOGO","n":"1.2","t":"A administração do servidor não se responsabiliza por quaisquer contas de jogadores, incluindo todos os itens, valores, propriedades ou bens contidos nelas.\nIsso significa que qualquer perda decorrente de hacking, fraude, compartilhamento de conta, descuido, desatenção ou qualquer outro tipo de violação de segurança é de total responsabilidade do jogador.\nRecomendamos que cada jogador mantenha sua conta segura, não compartilhe dados de acesso e utilize autenticações adicionais sempre que possível.","p":""},{"g":"Regras do jogo","b":"POLÍTICA DE CONTAS DO JOGO","s":"POLÍTICA DE CONTAS DO JOGO","n":"1.3","t":"É estritamente proibida a transferência, venda, troca ou empréstimo de contas de jogo para terceiros.\nQualquer tentativa ou realização desse ato resultará em banimento permanente da conta envolvida.\nPunição: banimento permanente","p":"banimento permanente"},{"g":"Regras do jogo","b":"POLÍTICA DE CONTAS DO JOGO","s":"POLÍTICA DE CONTAS DO JOGO","n":"1.4","t":"É proibido utilizar nomes com conotação sexual ou apologia ao crime no nickname do jogo.\nQualquer nome que se enquadre nessas situações terá a conta bloqueada automaticamente, sem aviso prévio.\nOutros nomes que não infrinjam as regras de conta serão tolerados, como por exemplo: “Th”, “Vulgo”, “Mnr” ou apelidos pelos quais o jogador é conhecido, desde que mantenham um padrão adequado e não violem nenhuma regra estabelecida.\nPunição: 7 dias de banimento","p":"7 dias de banimento"},{"g":"Regras do jogo","b":"POLÍTICA DE CONTAS DO JOGO","s":"POLÍTICA DE CONTAS DO JOGO","n":"1.5","t":"É terminantemente proibido utilizar nicknames que contenham palavrões, insultos, termos ofensivos, (incluindo versões disfarçadas ou abreviadas) ou qualquer linguagem considerada inadequada.\nPunição: 7 dias de banimento","p":"7 dias de banimento"},{"g":"Regras do jogo","b":"POLÍTICA DE CONTAS DO JOGO","s":"POLÍTICA DE CONTAS DO JOGO","n":"1.6","t":"É proibido criar um nickname que seja repetitivo, muito semelhante ou que imite o nickname de outros jogadores, administradores ou qualquer membro da equipe, seja na escrita, pronúncia ou formatação.\nEssa prática gera confusão, dificulta a identificação e pode ser interpretada como tentativa de se passar por outra pessoa.\nPenalidades:\nAdvertência (Warn)\nObrigação de alterar o nickname imediatamente\nPermaban em casos de tentativa clara de se passar por administradores, staff ou causar prejuízo a terceiros\nPunição: 10 dias de banimento","p":"Advertência (Warn)\nObrigação de alterar o nickname imediatamente"},{"g":"Regras do jogo","b":"POLÍTICA DE CONTAS DO JOGO","s":"POLÍTICA DE CONTAS DO JOGO","n":"1.17","t":"É proibido CC (Cortar Caminho).\nÉ considerado CC o ato de utilizar veículos (carro ou moto) para dirigir por campos, calçadas, áreas gramadas, terrenos irregulares ou qualquer local fora da via destinada à circulação, com o objetivo de encurtar caminho ou obter vantagem indevida.\nO CC será aplicado em quebras de ações e não será tolerado durante qualquer tipo de ação envolvendo organizações governamentais ou criminosas, incluindo ações de rua, perseguições, operações, guerras, fugas ou abordagens.\nPunição: Prisão de 15 minutos.","p":"Prisão de 15 minutos."},{"g":"Regras do jogo","b":"POLÍTICA DE CONTAS DO JOGO","s":"POLÍTICA DE CONTAS DO JOGO","n":"1.18","t":"É proibido ABUSE (abuso de poder policial), caracterizado pelo uso indevido da autoridade fora dos padrões do RP ou das regras do servidor.\nPunição: Prisão de 60 minutos | Ban de 20 a 30 dias | IP em casos mais graves.","p":"Prisão de 60 minutos | Ban de 20 a 30 dias | IP em casos mais graves."},{"g":"Regras do jogo","b":"POLÍTICA DE CONTAS DO JOGO","s":"POLÍTICA DE CONTAS DO JOGO","n":"1.19","t":"É proibido DMEDIC (Deathmatch contra médicos) qualquer ato de DM contra médicos em serviço.\nPunição: Ban 20 dias / Ban IP.","p":"Ban 20 dias / Ban IP."},{"g":"Regras do jogo","b":"POLÍTICA DE CONTAS DO JOGO","s":"POLÍTICA DE CONTAS DO JOGO","n":"1.20","t":"Os Administradores Staffs\npossuem total autoridade para aplicar banimentos acompanhados da orientação “CONTATE O SUPORTE”.\nEssa medida se aplica nas seguintes situações:\nQuando houver denúncia formal contra o jogador e ele não estiver presente no servidor ou no Discord;\nQuando o jogador não estiver visível para a administração e houver indícios ou provas de irregularidades dentro do servidor;\nQuando for necessário encaminhar o caso para análise completa pela equipe de suporte.\nNesses casos, o banimento será aplicado preventivamente e o jogador deverá entrar em contato com o suporte para verificação e possível revisão da punição.\nPunição: 365 dias de banimento","p":".\nPunição: 365 dias de banimento"},{"g":"Regras do jogo","b":"TERMINOLOGIA DAS PENALIDADES","s":"TERMINOLOGIA DAS PENALIDADES","n":"2.1","t":"Advertência Verbal\nA advertência verbal é um aviso direto dado por um administrador para alertar o jogador sobre uma conduta inadequada.\nSeu objetivo é orientar e garantir que o jogador corrija o comportamento antes que medidas punitivas mais severas sejam aplicadas.","p":""},{"g":"Regras do jogo","b":"TERMINOLOGIA DAS PENALIDADES","s":"TERMINOLOGIA DAS PENALIDADES","n":"2.2","t":"Kick\nO Kick consiste na desconexão imediata do jogador do servidor, realizada por um administrador.\nÉ utilizado para interromper comportamentos inadequados, aplicar correções rápidas ou alertar o jogador de que sua conduta precisa ser ajustada. O Kick não possui caráter punitivo definitivo, sendo uma medida administrativa preventiva para manter a organização e o bom funcionamento do servidor.\nPoderá resultar em Kick, por exemplo:\n• Azaralho no HP (Hospital), prejudicando atendimentos ou o RP médico.\n• Azaralho no VOIP, gritando, poluindo comunicação ou impedindo o RP dos demais.\n• Atrapalhar outros jogadores durante interações de RP, abordagens ou cenas em andamento.\n• Desrespeito leve a regras de conduta ou falta de bom senso que não exija punição maior.\n• Permanecer AFK em locais que prejudiquem o fluxo do servidor (filas, atendimentos, eventos).\n• Desorganizar eventos administrativos ou ações oficiais em andamento.","p":"maior.\n• Permanecer AFK em locais que prejudiquem o fluxo do servidor (filas, atendimentos, eventos)."},{"g":"Regras do jogo","b":"TERMINOLOGIA DAS PENALIDADES","s":"TERMINOLOGIA DAS PENALIDADES","n":"2.3","t":"Mute\nO Mute é a penalidade que bloqueia o acesso do jogador ao chat de texto, impedindo-o de enviar mensagens por um período determinado.\nEssa punição é aplicada em casos de spam, ofensas, comportamento tóxico, uso indevido do chat ou violação das normas de comunicação do servidor.","p":"que bloqueia o acesso do jogador ao chat de texto, impedindo-o de enviar mensagens por um período determinado.\nEssa punição é aplicada em casos de spam, ofensas, comportamento tóxico, uso indevido do chat ou violação das normas de comunicação do servi"},{"g":"Regras do jogo","b":"TERMINOLOGIA DAS PENALIDADES","s":"TERMINOLOGIA DAS PENALIDADES","n":"2.4","t":"Jail\nO Jail é a penalidade que coloca o jogador em isolamento dentro de um local específico do servidor, por um tempo determinado.\nEssa medida é utilizada para punir infrações mais graves ou reincidentes, garantindo que o jogador cumpra uma punição temporária sem interferir na experiência dos demais.","p":"que coloca o jogador em isolamento dentro de um local específico do servidor, por um tempo determinado.\nEssa medida é utilizada para punir infrações mais graves ou reincidentes, garantindo que o jogador cumpra uma punição temporária sem interfe"},{"g":"Regras do jogo","b":"TERMINOLOGIA DAS PENALIDADES","s":"TERMINOLOGIA DAS PENALIDADES","n":"2.5","t":"Warn\nO Warn é um aviso formal aplicado ao jogador, registrando uma infração significativa das regras e podendo impor restrições temporárias.\nEssa penalidade serve como um alerta para que o jogador ajuste seu comportamento, pois o acúmulo de Warns leva a punições mais severas.\nNota:\nAo receber um Warn, o jogador será automaticamente removido de qualquer facção da qual faça parte.\nAlém disso, será aplicado um bloqueio de 24 horas de jogo que impede o jogador de entrar em qualquer facção durante esse período.\nApós completar as 24 horas de jogo, o jogador poderá se juntar novamente a uma facção, porém o Warn permanecerá registrado em sua conta.\nCaso o jogador acumule 3 Warns, sua conta será automaticamente bloqueada por 10 dias.","p":"serve como um alerta para que o jogador ajuste seu comportamento, pois o acúmulo de Warns leva a punições mais severas."},{"g":"Regras do jogo","b":"TERMINOLOGIA DAS PENALIDADES","s":"TERMINOLOGIA DAS PENALIDADES","n":"2.6","t":"Ban\nO Ban consiste em bloquear a conta do jogador, impedindo seu acesso ao servidor por um período determinado ou permanentemente, dependendo da gravidade da infração.\nBan IP:\nO Ban IP bloqueia o dispositivo ou endereço de IP utilizado pelo jogador, impossibilitando o acesso ao servidor independentemente da conta utilizada.\nEssa penalidade é aplicada em casos mais graves, como hacks, fraudes, abusos severos ou reincidências.","p":"é aplicada em casos mais graves, como hacks, fraudes, abusos severos ou reincidências."},{"g":"Regras do jogo","b":"TERMINOLOGIA DAS PENALIDADES","s":"TERMINOLOGIA DAS PENALIDADES","n":"2.7","t":"Permaban\nO Permaban é o bloqueio permanente da conta do jogador, impedindo o acesso ao servidor de forma definitiva.\nEssa penalidade é aplicada apenas em casos extremamente graves ou quando o jogador demonstra reincidência severa em infrações consideradas intoleráveis.","p":"é aplicada apenas em casos extremamente graves ou quando o jogador demonstra reincidência severa em infrações consideradas intoleráveis."},{"g":"Regras do jogo","b":"TERMINOLOGIA DAS PENALIDADES","s":"TERMINOLOGIA DAS PENALIDADES","n":"2.8","t":"Report Mute\nO Report Mute é a penalidade que bloqueia o uso da função de reportar problemas, dúvidas ou denúncias dentro do servidor.\nEssa punição é aplicada quando o jogador utiliza o sistema de report de forma inadequada, abusiva, com spam ou para fins não relacionados ao suporte.\nDurante o período do Report Mute, o jogador não poderá enviar relatórios, devendo aguardar o término da penalidade para voltar a utilizar o recurso normalmente.\nPenalidade: mute 40 minutos","p":"que bloqueia o uso da função de reportar problemas, dúvidas ou denúncias dentro do servidor.\nEssa punição é aplicada quando o jogador utiliza o sistema de report de forma inadequada, abusiva, com spam ou para fins não relacionados ao"},{"g":"Regras do jogo","b":"TERMINOLOGIA DAS PENALIDADES","s":"TERMINOLOGIA DAS PENALIDADES","n":"2.9","t":"Reinicialização de Conta\nA Reinicialização de Conta é a penalidade que remove completamente todos os bens, itens e progressos do jogador, deixando a conta em estado inicial, como se estivesse começando do zero.\nEssa punição é aplicada em casos graves, geralmente relacionados a abuso de sistemas, exploração de bugs, fraudes ou violações sérias das regras.\nNota:\nA reinicialização inclui a exclusão completa de:\nTodos os fundos monetários (banco e carteira)\nNúmero de telefone\nSkin do personagem\nVeículos (incluindo placas personalizadas)\nPropriedades (casas, apartamentos, escritórios, garagens etc.)\nEmpresas de transporte ou construção\nNegócios e estabelecimentos adquiridos\nPostos de gasolina\nVínculo com famílias (desligamento automático)\nInventário completo (todos os itens são removidos)\nApós a reinicialização, o jogador mantém apenas a conta em si, sem qualquer bem, valor ou vínculo no servidor.","p":"que remove completamente todos os bens, itens e progressos do jogador, deixando a conta em estado inicial, como se estivesse começando do zero.\nEssa punição é aplicada em casos graves, geralmente relacionados a abuso de sistemas, exploração de bugs, fraudes ou violações sérias das re"},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","n":"3.1","t":"É proibido fugir deliberadamente do processo de Roleplay por quaisquer meios.\nTodo jogador deve manter o RP ativo e contínuo durante interações que afetam seu personagem.\nQualquer tentativa de evitar, escapar ou interromper intencionalmente uma situação de RP é considerada quebra grave das regras.\nNota | Exemplos de violações:\nFicar AFK durante uma abordagem policial ou situação de conflito para evitar consequências.\nSair do jogo (quit) para impedir a própria morte, prisão, sequestro ou qualquer resultado negativo para o personagem.\nIgnorar completamente interações de outro jogador, quando essas interações impactam de forma direta o seu personagem.\nEntrar em interiores, safe zones ou áreas verdes durante um tiroteio com a intenção de escapar da morte ou fugir do RP.\nUsar desculpas IC ou OOC para não seguir uma ação já iniciada que claramente envolve seu personagem.\nEssas atitudes prejudicam a narrativa, quebram a imersão e afetam diretamente a experiência dos demais jogadores.\nPenalidades: punição aplicada de acordo com uma quebra de regra apresentada da situação, por exemplo: kitou utilizem CL","p":"punição aplicada de acordo com uma quebra de regra apresentada da situação, por exemplo: kitou utilizem CL"},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","n":"3.2","t":"É proibido USE (uso indevido de veículo) utilizar veículos de trabalho ou pertencentes a qualquer organização/facção para fins pessoais, fora de serviço ou sem autorização.\nÉ estritamente proibido:\nUsar veículos de trabalho ou da organização para fins pessoais, como lazer, transporte próprio, práticas ilegais ou qualquer atividade que não esteja vinculada à função atribuída.\nUsar veículos pessoais para realizar trabalhos de organizações, seja para obter vantagem, acelerar processos ou substituir veículos oficiais.\nEssas ações quebram o realismo do RP e podem gerar desequilíbrio nas atividades organizacionais.\nPenalidade: Cadeia (Jail) de 40 minutos","p":"Cadeia (Jail) de 40 minutos"},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","n":"3.3","t":"Proibição de Divulgação Comercial\nÉ estritamente proibido anunciar, promover ou divulgar qualquer tipo de projeto externo, incluindo:\nOutros servidores de jogo\nServidores Discord externos\nSites ou plataformas não relacionadas ao RioRise\nCanais do YouTube, lives ou conteúdos visando captar jogadores\nCódigos promocionais\nQualquer forma de propaganda comercial ou divulgação com fins de ganho próprio ou direcionamento de público\nA prática de divulgação dentro do servidor quebra as diretrizes de convivência e compromete o ambiente do projeto.\nPenalidades:\nBanimento de 10 dias\nPossibilidade de Ban IP, dependendo da gravidade e intenção","p":"Banimento de 10 dias\nPossibilidade de Ban IP, dependendo da gravidade e intenção"},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","n":"3.4","t":"Proibição de Trocas Envolvendo Doações\nÉ terminantemente proibido trocar, vender, negociar ou oferecer benefícios de doação em troca de quaisquer valores dentro do jogo, incluindo:\nDinheiro in-game\nItens\nVeículos\nPropriedades\nServiços\nQualquer outro recurso do servidor\nDoações são exclusivamente destinadas ao apoio ao projeto, não podendo ser utilizadas como moeda de troca dentro do RP ou do servidor.\nPenalidade:\nBanimento Permanente (Permaban)\nReinicialização completa da conta","p":"Banimento Permanente (Permaban)\nReinicialização completa da conta"},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","n":"3.5","t":"É proibido enganar a administração em qualquer recurso do projeto\nPenalidade padrão: Ban 5 dias\nÉ considerado infração grave qualquer tentativa de enganar, manipular, distorcer informações ou prejudicar a administração para obter vantagens indevidas ou influenciar decisões da equipe.\nExemplos de violações:\nFalsificação de provas\nDistorção de informações para benefício próprio\nFornecimento intencional de informações incompletas sobre uma situação\nQualquer tentativa deliberada de manipular a equipe de administração ou o sistema do servidor\nNotas Importantes:\n• Falsificação de provas:\nA falsificação de qualquer tipo de prova poderá resultar em banimento permanente (Permaban) da conta onde a fraude foi cometida, incluindo todas as outras contas pertencentes ao infrator, a critério dos Staffs.\n• Serviços para burlar processos administrativos:\nServiços pagos ou gratuitos que ofereçam vantagens indevidas, como \"passar pesquisas\", facilitar testes, entrevistas ou processos de seleção\", também poderão resultar em banimento permanente do projeto.\nPenalidade: Permaban.","p":"Ban 5 dias\nÉ considerado infração grave qualquer tentativa de enganar, manipular, distorcer informações ou prejudicar a administração para obter vantag"},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","n":"3.6","t":"É proibido vender, trocar ou comprar qualquer parte incentivadora do projeto\nÉ terminantemente proibido vender, trocar, negociar ou comprar qualquer benefício incentivador concedido gratuitamente pelo\nprojeto, incluindo:\nCódigos de bonificação\nCódigos promocionais\nVouchers, premiações, bônus ou qualquer item entregue ao jogador como parte de eventos, promoções ou ações especiais da administração\nEsses incentivos são fornecidos sem custo para incentivar a participação dos jogadores, e não devem ser utilizados como moeda de troca ou fonte de lucro dentro ou fora do servidor.\nPenalidades:\nMute de 40 minutos\nBanimento entre 1 e 5 dias, dependendo da gravidade","p":"Mute de 40 minutos\nBanimento entre 1 e 5 dias, dependendo da gravidade"},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","n":"3.7","t":"É proibido permanecer AFK no servidor\nOs jogadores não podem ficar AFK (ausentes) em nenhuma área do servidor, independentemente do local.\nFicar AFK ocupa vaga de conexão, prejudica o desempenho e atrapalha o fluxo de jogadores ativos.\nPenalidade:\nKick (Chute)","p":"Kick (Chute)"},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","n":"3.8","t":"É proibido dormir em locais públicos ou em áreas de trabalho\nO jogador não pode utilizar o comando ou animação de dormir em locais públicos, áreas movimentadas, pontos de trabalho ou qualquer ambiente que interfira no fluxo do servidor ou prejudique a imersão do RP.\nPenalidade:\nKick (Chute)","p":"Kick (Chute)"},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","n":"3.9","t":"É proibido nomear itens do jogo utilizando linguagem imprópria\nÉ estritamente proibido atribuir nomes a itens do jogo contendo:\nLinguagem imprópria ou ofensiva\nXingamentos ou insultos\nConotações políticas\nConotações religiosas\nQualquer tipo de termo que viole as diretrizes de convivência do servidor\nEssa regra se aplica a qualquer item customizável, incluindo armas, veículos, roupas, mochilas e demais objetos renomeáveis.\nPenalidades:\nBanimento de 1 dia\nBanimento Permanente em caso de reincidência do mesmo erro\nNota:\nIsso inclui também nomes de Famílias, Organizações, Empresas ou qualquer outro grupo criado dentro do servidor.","p":"Banimento de 1 dia\nBanimento Permanente em caso de reincidência do mesmo erro"},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","n":"3.10","t":"É proibido ocultar bugs do sistema da administração, assim como utilizá-los,repassá-los ou compartilhá-los com outros jogadores.\nPenalidade: Banimento de 3/5 dias | Banimento Permanente / Banimento por IP (dependendo da gravidade).\nExplicação:\nQualquer falha encontrada no jogo deve ser imediatamente comunicada à administração. Esconder bugs, utilizá-los em benefício próprio ou distribuí-los para outras pessoas é considerado uma violação grave, pois compromete o equilíbrio e a integridade do servidor.","p":"Banimento de 3/5 dias | Banimento Permanente / Banimento por IP (dependendo da gravidade)."},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","n":"3.11","t":"É proibido tentar causar danos à economia do servidor, incluindo comprar ou vender qualquer moeda ou item do jogo com dinheiro real, seja entre jogadores ou por meio de sites terceiros.\nA compra de moedas ou benefícios só pode ser feita pelo site oficial do projeto.\nPenalidade: Ban 365 / 3650 dias por IP | Banimento Permanente | Reset completo da conta.\nNota:\nQualquer tentativa de compra, venda, troca ou até mesmo buscar informações com outros jogadores sobre esse tipo de negociação é considerada infração e será punida.\nOutros exemplos de ações proibidas:\nJogador com grande quantidade de dinheiro ou propriedades distribuindo valores, itens ou bens para outros jogadores sem justificativa dentro do Roleplay.\nDistribuição de dinheiro, propriedades, carros fortes, códigos ou qualquer item que gere lucro ou afete a economia do servidor.\nEssas ações desestabilizam o equilíbrio econômico e prejudicam a experiência de todos os demais jogadores.","p":"Ban 365 / 3650 dias por IP | Banimento Permanente | Reset completo da conta."},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","n":"3.13","t":"Quebra excessiva das regras do servidor\nPunição: Banimento de 7 dias.\nNota: Considera-se quebra excessiva quando há três ou mais violações das regras do servidor cometidas dentro de um período de 7 dias.\nExemplo: Três punições por DM; a quarta infração será considerada abuso. Da mesma forma, caso haja uma punição por menção a familiares, duas por VDM e duas por DM, a próxima infração, independentemente do tipo, será enquadrada como abuso.","p":"Banimento de 7 dias."},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","n":"3.14","t":"Ações destrutivas contra o projeto\nPunição: Banimento permanente, emitido em concordância com a STAFF.\nNota: Considera-se ação destrutiva qualquer atitude que cause prejuízo direto ou indireto ao projeto, seja dentro ou fora do servidor, incluindo tentativas de desestabilização, difamação, incentivo ao descumprimento de regras ou qualquer conduta que comprometa a integridade do projeto.","p":"Banimento permanente, emitido em concordância com a STAFF."},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","n":"3.15","t":"Tentativa de venda de propriedades ou contas do jogo por dinheiro real.\nPunição: Banimento de 30 dias, Ban IP ou Banimento permanente.\nNota: Qualquer tentativa de venda, troca ou negociação de propriedades do jogo ou contas envolvendo dinheiro real será enquadrada nesta regra, independentemente da conclusão da negociação. Esta infração se enquadra na regra 3.12, estando sujeita às punições correspondentes conforme a gravidade e reincidência.","p":"Banimento de 30 dias, Ban IP ou Banimento permanente."},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","n":"3.16","t":"Venda, transferência ou manipulação da reputação de família\nPunição: Redefinição da família ( RESET )\nNota: É proibida a venda, compra ou transferência da reputação da família por qualquer meio, bem como a ocultação de infratores ou trapaceiros por parte do líder da facção ou da família. Qualquer tentativa de burlar o sistema de punições ou proteger membros infratores será enquadrada nesta regra.","p":"Redefinição da família ( RESET )"},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","n":"3.17","t":"É proibido falar em OOC, exceto quando um administrador fizer perguntas importantes fora do IC.\nExplicação:\nIC (In Character): Tudo que acontece dentro do personagem, ou seja, ações, falas e decisões que fazem parte da história do seu personagem no roleplay. Exemplo: conversar como se fosse seu personagem, reagir a situações do jogo, seguir a narrativa do RP.\nOOC (Out of Character): Tudo que é fora do personagem, ou seja, assuntos pessoais, dúvidas sobre regras, problemas técnicos ou qualquer conversa que não faça parte da história do RP. Exemplo: falar sobre Discord, reclamar de regra, perguntar algo administrativo ou comentar algo da vida real.\nResumo: Durante o RP, você deve agir e falar sempre em IC. O uso de OOC só é permitido quando um administrador solicitar ou fizer perguntas importantes fora do personagem.\nPunição: Jail por 30 minutos.","p":"Jail por 30 minutos."},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","n":"3.18","t":"É proibido qualquer tipo de tratamento desrespeitoso, insulto, comportamento inadequado ou ameaça, sob qualquer forma, direcionados à administração.\nPunição: Banimento por 5 dias / Casos de acúmulos a Insultos podem ser IP","p":"Banimento por 5 dias / Casos de acúmulos a Insultos podem ser IP"},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","n":"3.19","t":"É proibido o VPA (Voltar Para a Ação), que consiste em retornar à ação em que morreu anteriormente. É obrigatório aguardar 15 minutos para retornar ao local.\nNota: Em ações de invasão e pacificação, o retorno só será permitido após a finalização completa da ação.\nPunição: Jail por 30 minutos | Banimento de 1 dia.","p":"Jail por 30 minutos | Banimento de 1 dia."},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","n":"3.20","t":"É proibida a prática de ASF (Ação em Zona Segura), ou qualquer tipo de ação dentro de Zona Segura (definida como SafeZone).\nPunição: Prisão por 30 minutos | Banimento de 1 dia.","p":"Prisão por 30 minutos | Banimento de 1 dia."},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","n":"3.21","t":"Em casos de Anti-RP ou atitudes que prejudiquem outros jogadores,  a punição adequada, de acordo com o padrão de punições estabelecido pelo servidor.","p":"adequada, de acordo com o padrão de punições estabelecido pelo servidor."},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"Penalidades: de acordo com a quebra de regra feita na ação","n":"3.22","t":"Ao ser removido de uma organização ou corporação, o jogador ficará impossibilitado de ingressar em outra pelo período de 24 horas.","p":""},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"Penalidades: de acordo com a quebra de regra feita na ação","n":"3.23","t":"É proibido praticar atos com a intenção de Forçar RP, ou seja, incitar ações que não condizem com a realidade do roleplay.\nExemplo: Andar com arma em mãos com o objetivo de chamar atenção, desafiar ou provocar outros personagens e policiais.\nPunição: Prisão por 40 minutos, Banimento por 5 dias ou Banimento por IP.","p":"Prisão por 40 minutos, Banimento por 5 dias ou Banimento por IP."},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"Penalidades: de acordo com a quebra de regra feita na ação","n":"3.24","t":"Assaltos seguidos de morte caracterizam DM (Deathmatch). Jogadores que aceitam o assalto de forma correta não devem ser mortos.\nPenalidade: cadeia 60 minutos","p":"cadeia 60 minutos"},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"Penalidades: de acordo com a quebra de regra feita na ação","n":"3.25","t":"É proibido se passar por um administrador sem possuir o cargo.\nPunição: Banimento de 5 a 15 dias ou Banimento por IP.","p":"Banimento de 5 a 15 dias ou Banimento por IP."},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"Penalidades: de acordo com a quebra de regra feita na ação","n":"3.26","t":"É proibido criar ruídos ou sons externos que prejudiquem a comunicação no jogo.\nNota: Incluem-se ruídos de fundo durante a fala que interfiram na interação dos jogadores pelo chat de voz, distorções intensas causadas por microfone de baixa qualidade e atitudes deliberadas para atrapalhar a experiência de outros jogadores, modificadores de voz (gritos, interrupções, etc.).\nPunição: Mute por 40 minutos.","p":"Mute por 40 minutos."},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"Penalidades: de acordo com a quebra de regra feita na ação","n":"3.27","t":"É proibida música no VoIP  fora das áreas permitidas.\nPunição: Mute por 40 minutos.","p":"Mute por 40 minutos."},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"Penalidades: de acordo com a quebra de regra feita na ação","n":"3.28","t":"É proibido realizar flood no chat de serviço, no chat do jogo ou em quaisquer outros canais de comunicação.\nPunição: Mute por 40 minutos.","p":"Mute por 40 minutos."},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"Penalidades: de acordo com a quebra de regra feita na ação","n":"3.29","t":"É proibido insultar outros jogadores ou seus familiares.\nPunição: Mute e Prisão por 30 minutos, casos graves banimento por 2 dias.","p":"Mute e Prisão por 30 minutos, casos graves banimento por 2 dias."},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"Penalidades: de acordo com a quebra de regra feita na ação","n":"3.30","t":"É expressamente proibido a prática de Dark RP no servidor, incluindo, mas não se limitando a: assédio, discriminação, importunação sexual, racismo, violência moral, homofobia e quaisquer outras práticas tóxicas.\nPunição: Banimento de 10 a 30 dias. Em casos mais graves, Banimento por 30 a 60 dias + | Banimento por IP.","p":"Banimento de 10 a 30 dias. Em casos mais graves, Banimento por 30 a 60 dias + | Banimento por IP."},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"Penalidades: de acordo com a quebra de regra feita na ação","n":"3.31","t":"É proibido o mau uso dos comandos /me, /do e /try.\nPunição: Mute por 40 minutos.\nUso correto:\n/me – Descreve ações realizadas pelo próprio personagem.\nExemplo: /me pega um copo d'água e o bebe com calma.\n/do – Descreve situações, estados ou acontecimentos do ambiente ao redor do personagem.\nExemplo: /do o vento sopra suavemente, acariciando os cabelos de Maria.\n/try – Utilizado para ações que possuem chance de sucesso ou falha.\nExemplo: /try tenta pegar um objeto que está no alto com as mãos.\nUso incorreto:\n/me – Forçar ações sobre outro personagem.\nExemplo incorreto: /me derruba João no chão e o deixa inconsciente.\n/do – Confirmar ações sem chance de reação de outro jogador.\nExemplo incorreto: /do João está desacordado e não pode reagir.\n/try – Usar para ações impossíveis ou para forçar resultado.\nExemplo incorreto: /try mata o personagem instantaneamente.","p":"Mute por 40 minutos.\nUso correto:"},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"Penalidades: de acordo com a quebra de regra feita na ação","n":"3.32","t":"É expressamente proibido realizar RP de desrespeito após vencer uma trocação, como provocar ou humilhar jogadores feridos, bem como praticar ações pesadas ou degradantes (ex.: urinar sobre o personagem). Também são proibidas quaisquer atitudes que caracterizem violência moral, discriminação, machismo ou outras formas de desrespeito ao jogador.\nObservação: São permitidas zoações leves que remetam à fraqueza do personagem, como chamá-lo de “fraco”, “tapete”, entre outras semelhantes, desde que não ultrapassem os limites do respeito.\nPunição: Prisão por 60 minutos / banimento 1 dia","p":"Prisão por 60 minutos / banimento 1 dia"},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"Penalidades: de acordo com a quebra de regra feita na ação","n":"3.33","t":"É proibido o uso excessivo de caixa alta (Caps Lock) ao escrever qualquer texto em qualquer chat.\nPunição: Mute por 10 minutos.","p":"Mute por 10 minutos."},{"g":"Regras do jogo","b":"REGRAS GERAIS DO PROCESSO DE ROLEPLAY","s":"Penalidades: de acordo com a quebra de regra feita na ação","n":"3.34","t":"É proibido drenar o armazém de uma facção ou família, retirando grandes quantidades de recursos ou valores superiores ao que foi devidamente autorizado.\nPunição: Prisão por 60 minutos. Caso os valores não sejam devolvidos, Banimento por 30 dias ou Banimento por IP.","p":"Prisão por 60 minutos. Caso os valores não sejam devolvidos, Banimento por 30 dias ou Banimento por IP."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.1","t":"É proibido a prática de MDM (Mass Deathmatch), que consiste em matar ou causar dano a três ou mais jogadores sem motivo válido dentro do RP.\nPunição: Prisão por 60 minutos, restrição de armas / Banimento de 3 a 7 dias.","p":"Prisão por 60 minutos, restrição de armas / Banimento de 3 a 7 dias."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.2","t":"PVP SEM MOTIVO\nÉ proibido iniciar PVP, disparar ou matar outro jogador sem possuir um motivo válido de Roleplay e sem interação prévia. Todo confronto deve possuir contexto e justificativa dentro do RP, sendo proibido iniciar ataques por diversão, vingança sem contexto, conflitos externos ao jogo ou apenas por pertencer a outra organização ou família. O PVP também é proibido em Zonas Seguras, independentemente do motivo.\nPunições:\n• 1ª ocorrência: Jail 60 minutos.\n• 2ª ocorrência no mesmo dia: Jail 120 minutos.\n• 3ª ocorrência: Banimento de 3 dias.\n• PVP em Zona Segura: Banimento de 3 dias.","p":""},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.3","t":"É proibido a prática de VDM (Vehicle Deathmatch), que consiste em atropelar jogadores de forma intencional.\nPunição: Prisão por 60 minutos / Banimento de 1 a 5 dias.","p":"Prisão por 60 minutos / Banimento de 1 a 5 dias."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.4","t":"É proibido MG (Metagaming), que consiste em utilizar informações obtidas fora do jogo para benefício próprio ou para prejudicar outro jogador.\nNota: É proibido o uso de emotions/emotes como “=D” no chat IC.\nPunição: Prisão por 60 minutos / Banimento de 1 a 3 dias.","p":"Prisão por 60 minutos / Banimento de 1 a 3 dias."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.5","t":"É proibido CL (Combat Log), que consiste em sair do jogo durante uma ação para obter benefício, como evitar ser sequestrado, morto ou preso.\nPunição: Prisão por 60 minutos / Banimento de 1 a 3 dias.","p":"Prisão por 60 minutos / Banimento de 1 a 3 dias."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.6","t":"É expressamente proibido DM (Deathmatch), que consiste em matar ou causar dano a outro jogador sem qualquer motivo válido dentro do RP.\nPunição: Prisão por 60 minutos / Banimento de 1 a 3 dias.","p":"Prisão por 60 minutos / Banimento de 1 a 3 dias."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.7","t":"É proibido RK (Revenge Kill), que consiste em matar ou causar dano a um jogador com o objetivo de vingança por ter sido morto em uma vida anterior.\nPunição: Prisão por 60 minutos / Banimento de 1 a 3 dias.","p":"Prisão por 60 minutos / Banimento de 1 a 3 dias."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.8","t":"É proibido SK (Spawn Kill), que consiste em matar ou causar dano a jogadores no território de qualquer facção ou organização, bem como em locais de spawn do jogador.\nPunição: Prisão por 60 minutos / Banimento de 1 a 5 dias.","p":"Prisão por 60 minutos / Banimento de 1 a 5 dias."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.9","t":"É proibido TK (Team Kill), que consiste em matar ou causar dano a um membro da própria facção ou de facção aliada, sem qualquer motivo válido dentro do RP.\nPunição: Prisão por 40 minutos / Banimento de 1 a 2 dias.","p":"Prisão por 40 minutos / Banimento de 1 a 2 dias."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.10","t":"É extremamente proibido cometer SAAV (Sem Amor à Vida): ato de não se importar com a própria vida no jogo, escolhendo morrer em vez de cooperar com a ação.\nPunição: prisão de 40 minutos / banimento de 1 a 3 dias.","p":"prisão de 40 minutos / banimento de 1 a 3 dias."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.11","t":"É proibido Flaming RP\nÉ o uso de ofensas, insultos ou discurso de ódio direcionado a outros jogadores durante o RP.\nPunição: De acordo com a gravidade | Prisão + Mute de 60 minutos / Banimento de 1 a 30 dias.","p":"De acordo com a gravidade | Prisão + Mute de 60 minutos / Banimento de 1 a 30 dias."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.12","t":"É proibido KOS (Kill On Sight / Mate à Vista)\nÉ o ato de matar outro jogador de organização, facção ou família à vista, sem motivo ou contexto de RP.\nExemplo: na vida real, você não mataria uma pessoa apenas por ela pertencer a uma corporação policial.\nPunição: Prisão de 60 minutos / Banimento de 1 a 5 dias.","p":"Prisão de 60 minutos / Banimento de 1 a 5 dias."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.13","t":"É proibido PK (Player Kill)\nRefere-se à morte do personagem, na qual o jogador perde toda a memória relacionada à pessoa que o matou e aos acontecimentos que levaram à sua morte. É proibido utilizar essas informações após o PK.\nPunição: Prisão de 60 minutos / Banimento de 1 a 5 dias.","p":"Prisão de 60 minutos / Banimento de 1 a 5 dias."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.14","t":"É proibido RPFW (Roleplay For The Win)\nÉ o ato de desenvolver um RP visando apenas o próprio benefício, onde o jogador busca sempre “ganhar”, ignorando consequências ou a lógica da vida real. Na vida real, ninguém vence todas as situações.\nExemplos:\nVenda de vagas ou benefícios em geral.\nIr para zona safe em meio a uma ação.\nTentar utilizar alguma regra para prejudicar outros jogadores ou se beneficiar intencionalmente.\nGuardar veículos de trabalho em locais\nprivados para obter vantagem.\nPunição: Prisão de 60 minutos / Banimento de 1 a 5 dias.","p":"Prisão de 60 minutos / Banimento de 1 a 5 dias."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.15","t":"É proibido MIX\nÉ o ato de misturar assuntos ou informações fora do RP dentro do RP, quebrando a imersão do personagem.\nPunição: Prisão de 60 minutos / Banimento de 1 a 5 dias.","p":"Prisão de 60 minutos / Banimento de 1 a 5 dias."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.16","t":"É proibido a criação de múltiplas contas para transferência de dinheiro\nÉ proibido criar ou utilizar várias contas com o objetivo de transferir dinheiro ou obter vantagens para a conta principal.\nNota:\nÉ estritamente proibido criar e utilizar múltiplas contas com o objetivo de se beneficiar de maneira injusta, prejudicar outros membros do servidor, ou manipular resultados de forma abusiva.\nIsso inclui, mas não se limita a:\nUtilizar várias contas para obter vantagens indevidas em eventos, guerras ou trocas.\nPrejudicar intencionalmente outros jogadores com ações coordenadas entre suas contas.\nTentar azaralhar ou sabotar servidores, eventos ou a comunidade como um todo.\nQualquer violação desta regra será punida com banimento . Não há tolerância para trapaças, manipulação ou ações que comprometam a integridade do servidor.\nPunição: Banimento de 30 dias / Banimento por IP / Permanente","p":"Banimento de 30 dias / Banimento por IP / Permanente"},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.17","t":"É proibido AAP (ATRAPALHAR AÇÃO PROPOSITALMENTE), que consiste em interferir de forma intencional em uma ação em andamento.\nExemplo: atrapalhar uma abordagem batendo em outros jogadores, gritando no VOIP, floodando o chat, entre outros.\nPunição: prisão 60 minutos | Ban 1–3 dias.","p":"prisão 60 minutos | Ban 1–3 dias."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.18","t":"É proibido DMA (DEATH MATCH AUTO) causar danos a veículos públicos ou pessoais sem motivo.\nPunição: chute | prisão 30 minutos.","p":"chute | prisão 30 minutos."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.19","t":"É proibido NRA (NON ROLEPLAY AMBIENTE) utilizar armas em locais públicos, como hospital, delegacia, prefeitura, feirinha, Igreja, leilões, locais de trabalho e praças.\nPunição: prisão 20 minutos.","p":"prisão 20 minutos."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.20","t":"É proibido AI (AÇÃO IRREGULAR)\nAto de invadir ou permanecer ao redor de propriedades privadas de outros jogadores, como casas e mansões, com o intuito de forçar uma ação, causando danos diretos ao RP de outrem.\nPunição: Ban 10 dias. Caso seja família em ação conjunta, sujeita a aviso | Ban IP.","p":"Ban 10 dias. Caso seja família em ação conjunta, sujeita a aviso | Ban IP."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.21","t":"É proibido INA (INVASÃO NÃO AUTORIZADA)\nÉ o ato de invadir locais, como organizações criminosas ou corporações, sem autorização prévia da Administração.\nPunição: Ban 5 dias.","p":"Ban 5 dias."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.22","t":"É proibido FAIL (AÇÃO FALHA)\nÉ o ato de executar ações de forma diferente do que está estabelecido nas regras.\nPunição: Prisão 60 minutos | Ban 3–5 dias | Warn.","p":"Prisão 60 minutos | Ban 3–5 dias | Warn."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.23","t":"É proibido TSC (TRANSFERÊNCIA SEM CONSENTIMENTO)\nÉ o ato de transferir itens para o administrador sem o consentimento do mesmo.\nPunição: Prisão 10 minutos.","p":"Prisão 10 minutos."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.24","t":"É proibido ECI (ENSINO DE COMANDOS INCORRETOS)\nÉ o ato de ensinar comandos incorretos a outros jogadores com o intuito de se beneficiar.\nPunição: Prisão 60 minutos | Ban 1 a 5 dias.","p":"Prisão 60 minutos | Ban 1 a 5 dias."},{"g":"Regras do jogo","b":"REGRAS DA BÍBLIA RP","s":"REGRAS DA BÍBLIA RP","n":"4.25","t":"É proibido TOS (VIOLAÇÃO DOS TERMOS DE USO DA COMUNIDADE)\nÉ o ato de violar os termos de uso da comunidade. Qualquer aplicação por TOS será realizada após verificação do nosso sistema quanto ao uso de violações.\nPunição: Ban permanente.","p":"Ban permanente."},{"g":"Regras do jogo","b":"REGRAS DE DENÚNCIAS E PUNIÇÕES","s":"REGRAS DE DENÚNCIAS E PUNIÇÕES","n":"5.1","t":"Denúncias que não obedecerem ao padrão definido, que não forem claras ou que apresentarem evidências de baixa qualidade não serão aceitas.","p":""},{"g":"Regras do jogo","b":"REGRAS DE DENÚNCIAS E PUNIÇÕES","s":"REGRAS DE DENÚNCIAS E PUNIÇÕES","n":"5.2","t":"Caso, na denúncia, o denunciante apareça em print ou vídeo cometendo Anti-RP, ele receberá punição juntamente com o denunciado.\nExemplo: denunciar SAAV e cometer SAAV junto com o denunciado.","p":"juntamente com o denunciado."},{"g":"Regras do jogo","b":"REGRAS DE DENÚNCIAS E PUNIÇÕES","s":"REGRAS DE DENÚNCIAS E PUNIÇÕES","n":"5.3","t":"É proibido conversas paralelas no chat de denúncias | Advertência | Mute 10+ minutos.","p":""},{"g":"Regras do jogo","b":"REGRAS DE DENÚNCIAS E PUNIÇÕES","s":"REGRAS DE DENÚNCIAS E PUNIÇÕES","n":"5.4","t":"É proibido forjar provas contra outro jogador | Punição aplicada em dobro em relação à penalidade que o acusado receberia.","p":"aplicada em dobro em relação à penalidade que o acusado receberia."},{"g":"Regras do jogo","b":"REGRAS DE DENÚNCIAS E PUNIÇÕES","s":"REGRAS DE DENÚNCIAS E PUNIÇÕES","n":"5.5","t":"Dias específicos para recorrer à punição, contados a partir da data da aplicação:\n1 dia para punições de prisão;\n3 dias para punições de banimento.\nApós esse prazo, os recursos/apelos não serão mais aceitos.","p":", contados a partir da data da aplicação:\n1 dia para punições de prisão;"},{"g":"Regras do jogo","b":"REGRAS DE DENÚNCIAS E PUNIÇÕES","s":"REGRAS DE DENÚNCIAS E PUNIÇÕES","n":"5.6","t":"As denúncias realizadas pelo Discord têm prazo de até 24 horas para serem analisadas, desde que a postagem seja feita no momento do ocorrido.\nDenúncias enviadas após 1 dia não serão analisadas, exceto em casos de maior gravidade, a critério do analista.","p":""},{"g":"Regras do jogo","b":"REGRAS DE DENÚNCIAS E PUNIÇÕES","s":"REGRAS DE DENÚNCIAS E PUNIÇÕES","n":"5.7","t":"Caso um player seja banido por 30 dias e possua um ou mais negócios, todas as propriedades serão resetadas pelo sistema.","p":""},{"g":"Regras do jogo","b":"ZONA SEGURA","s":"ZONA SEGURA","n":"6.1","t":"As Zonas Seguras (SafeZone) são locais onde é proibido cometer qualquer tipo de violência.\nElas incluem:\nEdifícios Governamentais:\nDepartamento Policial, Hospital, Autoescola, Bancos, Câmara Municipal.\nTrabalhos Iniciais:\nMina, Obra e Fazenda.\nNegócios:\n24/7, Lanchonete, Vestuário, Loja de Armas, Lojinha de Acessórios, Posto de Gasolina, Bar, Concessionária de Carros Econômicos, Concessionária de Motos e Bicicletas, Centro de Serviços, Dragon Cassino 4, Ateliê de Customização Automotiva.","p":""},{"g":"Regras do jogo","b":"REGRAS DE AÇÕES DE RUA","s":"REGRAS DE AÇÕES DE RUA","n":"7.1","t":"As ações de rua devem ocorrer exclusivamente entre 08:00 e 00:00, sendo obrigatório respeitar um intervalo mínimo de 30 minutos entre cada ação, as ações de rua são válidas apenas para organizações criminosas.\nPenalidade: 60 minutos de cadeia  ( 4.22 - FAIL )","p":"60 minutos de cadeia  ( 4.22 - FAIL )"},{"g":"Regras do jogo","b":"REGRAS DE AÇÕES DE RUA","s":"REGRAS DE AÇÕES DE RUA","n":"7.2","t":"É proibido assaltar trabalhadores legais enquanto estiverem em serviço, como por exemplo: taxista, caminhoneiro, motorista de ônibus, minerador, agricultor e lixeiro, entre outros trabalhos legais.\nPenalidade: 60 minutos de cadeia  ( 4.22 - FAIL )","p":"60 minutos de cadeia  ( 4.22 - FAIL )"},{"g":"Regras do jogo","b":"REGRAS DE AÇÕES DE RUA","s":"REGRAS DE AÇÕES DE RUA","n":"7.3","t":"É proibido atirar ou render negociantes durante a ação.\nPenalidade: 60 minutos de cadeia  ( 4.22 - FAIL )","p":"60 minutos de cadeia  ( 4.22 - FAIL )"},{"g":"Regras do jogo","b":"REGRAS DE AÇÕES DE RUA","s":"REGRAS DE AÇÕES DE RUA","n":"7.4","t":"Deve haver maior número de sequestradores do que vítimas, sendo obrigatório que todos os envolvidos do lado dos sequestradores estejam portando arma de fogo.\nPenalidade: 60 minutos de cadeia ( 4.22 - FAIL )","p":"60 minutos de cadeia ( 4.22 - FAIL )"},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"REGRAS DE FAMÍLIA","n":"8.1","t":"A hierarquia de direitos da família é dividida em cinco níveis, sendo:\n4º nível: Vice-líder da família\n5º nível: Líder da família","p":""},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"REGRAS DE FAMÍLIA","n":"8.2","t":"O líder e o vice-líder da família podem aplicar advertências aos membros por infrações às regras da família, sendo obrigatório informar o motivo da advertência.\nParágrafo único: Ao acumular 3 advertências, o membro poderá ser expulso da família pelo líder ou vice-líder.","p":""},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"REGRAS DE FAMÍLIA","n":"8.3","t":"Todas as punições devem ser aplicadas rigorosamente de acordo com o regulamento e as regras da família e do servidor.","p":""},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"REGRAS DE FAMÍLIA","n":"8.4","t":"Foram removidos os itens 13.5, 13.6, 13.7 e 13.8 das regras anteriores da família.","p":""},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.5","t":"É proibido insultar membros da própria família.\nPunição: Advertência pelo líder da família","p":"Advertência pelo líder da família"},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.6","t":"É proibido danificar ou prejudicar qualquer propriedade da família.\nPunição: Advertência pelo líder da família","p":"Advertência pelo líder da família"},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.7","t":"É proibido ignorar mensagens, ordens ou solicitações de superiores hierárquicos relacionadas a você.\nPunição: Advertência pelo líder da família","p":"Advertência pelo líder da família"},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.8","t":"É proibido provocar conflitos com outras famílias.\nPunição: Advertência pelo líder da família","p":"Advertência pelo líder da família"},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.9","t":"Não é permitido pedir promoção de rank dentro da família.\nPunição: Advertência ou observação verbal\nMulta da Família","p":"Advertência ou observação verbal\nMulta da Família"},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.10","t":"A multa da família é uma punição aplicada na família do servidor, quando forem identificados múltiplos casos de infração às regras do servidor cometidos por seus membros.","p":"aplicada na família do servidor, quando forem identificados múltiplos casos de infração às regras do servidor cometidos por seus membros."},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.11","t":"A penalidade consiste na obrigação de pagamento de uma quantia em dinheiro, definida pela Staff, dentro de um prazo estabelecido.","p":"consiste na obrigação de pagamento de uma quantia em dinheiro, definida pela Staff, dentro de um prazo estabelecido."},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.12","t":"O valor da multa varia conforme:\nTipo de família\nQuantidade de infrações\nCooperação da liderança\nComportamento geral dos membros","p":""},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.13","t":"A não quitação da multa dentro do prazo estipulado pode resultar na exclusão da família.\nPunição: reset + restrição de 3 meses ( 90 dias )","p":"reset + restrição de 3 meses ( 90 dias )"},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.14","t":"A multa deverá ser paga com supervisão do Staffs, caso contrário.\nExclusão da Família","p":""},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.15","t":"A família poderá ser excluída do servidor nos seguintes casos:\nReincidência grave de infrações às regras do servidor\nFalta de pagamento de multas aplicadas\nFalta de controle da liderança sobre os membros\nEnvolvimento contínuo em ações ilegais ou anti regra\nPunição: reset","p":"reset"},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.16","t":"A reformulação da família antes do término do prazo de restrição resultará no reset da mansão do líder da família.\nPunição: reset\nExclusão da Família","p":"reset\nExclusão da Família"},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.17","t":"A exclusão da família é uma punição aplicada a critério do suporte Claudino, quando forem identificados casos recorrentes de infrações às regras do servidor cometidas por membros da família.\nPunição: reset","p":"aplicada a critério do suporte Claudino, quando forem identificados casos recorrentes de infrações às regras do servidor cometidas por membros da família.\nPunição: reset"},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.18","t":"Caso a família já tenha sido multada anteriormente, em uma nova reincidência a administração poderá aplicar a exclusão da família, substituindo a multa.","p":""},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.19","t":"A exclusão da família não será aplicada em casos de primeira infração, salvo em situações excepcionais, onde a gravidade da conduta justifique a medida.","p":""},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.20","t":"A exclusão da família deverá ser obrigatoriamente acordada com a staff da administração e só será executada após aprovação formal de sua parte.\nSistema de Advertências da Família","p":""},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.21","t":"Cada família possui um limite de infrações, considerando o tipo de família, seguindo o seguinte controle:\nAdvertências formais: [0/3]\nAdvertências verbais: [0/05]","p":""},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.22","t":"Ao atingir 05+ advertências verbais, estas serão convertidas automaticamente em 1 advertência formal.\nPunição: 1/3 aviso","p":"1/3 aviso"},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.23","t":"Ao atingir 3/3 advertências formais, a Staff poderá aplicar uma multa à família.\nPunição: Multa","p":"Multa"},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.24","t":"Caso a família atinja novamente o limite de 3/3 advertências formais após já ter sido multada, a Staff poderá aplicar a segunda multa na família.\nPunição: Segunda multa","p":"Segunda multa"},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.25","t":"As infrações da família são contabilizadas, em regra, dentro de um período de até 3 meses.","p":""},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.26","t":"Venda de moeda virtual, contas ou qualquer outro tipo de propriedade envolvendo a família.\nPunição: reset","p":"reset"},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.27","t":"Proibição absoluta de trazer jogadores de outros servidores para aumentar membros de forma fraudulenta\nÉ estritamente proibido que membros de uma família ou máfia tragam intencionalmente jogadores de outros servidores apenas para participar de guerras de família ou tomadas de máfia, com o objetivo de inflar o número de membros e obter vantagens desleais.\nQualquer tentativa ou prova dessa prática resultará em punições severas como aviso direto a família imediato, sem aviso prévio. Essa conduta prejudica a integridade do servidor e será combatida com rigor.\nAtenção: Não toleraremos manipulações que comprometam a justiça e o equilíbrio da comunidade. Faça sua parte e jogue de forma honesta!\nPunição: 1/3 aviso","p":"1/3 aviso"},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.28","t":"Jogadores da família que enganem outros jogadores envolvendo itens do jogo.\nPunição: Até 3 advertências verbais, possível para aviso","p":"Até 3 advertências verbais, possível para aviso"},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.29","t":"Insultar a administração ou seus familiares, seja dentro do jogo, fórum ou mensageiros oficiais.\nPunição: 1 advertência verbal, caso persiste resultará em 1/3 aviso","p":"1 advertência verbal, caso persiste resultará em 1/3 aviso"},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.30","t":"DM em massa, quando a família for flagrada com mais de 3 membros cometendo DM simultaneamente.\nPunição: 1/3 aviso","p":"1/3 aviso"},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Proibições Internas da Família","n":"8.31","t":"Comportamento inadequado recorrente, quando membros da família acumularem mais de 5 mutes por comportamento inadequado ou insultos.\nPunição: 1 advertências verbal, caso persiste resultará em 1/3 aviso","p":"1 advertências verbal, caso persiste resultará em 1/3 aviso"},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Considerações Gerais","n":"8.33","t":"O RioRise é um jogo de simulação de vida no Brasil, desenvolvido para proporcionar imersão, diversão e realismo, sendo todas as regras elaboradas para garantir a melhor experiência possível aos jogadores.","p":""},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Considerações Gerais","n":"8.34","t":"Qualquer punição ou banimento aplicado é de responsabilidade exclusiva do jogador, decorrente do descumprimento direto ou indireto das regras.","p":"ou banimento aplicado é de responsabilidade exclusiva do jogador, decorrente do descumprimento direto ou indireto das regras."},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Considerações Gerais","n":"8.35","t":"É extremamente proibido qualquer tipo de assédio, discurso de ódio, preconceito ou comportamento tóxico, sendo tais condutas passíveis de banimento.","p":""},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Considerações Gerais","n":"8.36","t":"Em caso de punição considerada indevida, o jogador deverá abrir revisão diretamente com o responsável pela punição, por meio do Discord oficial do servidor.","p":"considerada indevida, o jogador deverá abrir revisão diretamente com o responsável pela punição, por meio do Discord oficial do servidor."},{"g":"Regras do jogo","b":"REGRAS DE FAMÍLIA","s":"Considerações Gerais","n":"8.37","t":"A história do seu personagem está em suas mãos:\ntorne-se um chefe de polícia combatendo o crime, ou ingresse no mundo do crime e construa seu império como chefe de máfia.","p":""}];
